const readDraft = (key, fallback) => {
  try {
    const saved = window.localStorage.getItem(key);
    return saved ? { ...fallback, ...JSON.parse(saved) } : fallback;
  } catch { return fallback; }
};
const saveDraft = (key, value) => {
  try { window.localStorage.setItem(key, JSON.stringify(value)); } catch { /* El formulario continúa aunque el navegador bloquee el borrador. */ }
};
const clearDraft = key => {
  try { window.localStorage.removeItem(key); } catch { /* sin acción */ }
};

