const nombreItem = (item) => {
  if (item?.productoId === "transporte_ruta") return "Transporte";
  const descripcion = String(item?.descripcion || "").trim();
  if (descripcion && descripcion.toLowerCase() !== "producto") return descripcion;
  return item?.productoNombre || item?.producto || item?.nombre || productoNombre(item?.productoId) || "Producto sin especificar";
};

async function storageGet(key, shared) {
  try {
    if (shared) return await getSharedData(key);
    const value = window.localStorage.getItem(key);
    return value ? JSON.parse(value) : null;
  } catch (e) { return null; }
}
async function storageSet(key, value, shared) {
  try {
    if (shared) await setSharedData(key, value);
    else window.localStorage.setItem(key, JSON.stringify(value));
  } catch (e) {
    console.error("No se pudo guardar la información:", e);
    throw e;
  }
}

function Badge({ estado }) {
  const c = ESTADO_COLOR[estado] || "gray";
  return <span className={`badge badge-${c}`}>{estado}</span>;
}

function LoginScreen({ onLogin }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [enviando, setEnviando] = useState(false);

  const entrar = async () => {
    if (!email.trim() || !password) {
      setError("Escribe tu correo y contraseña para continuar.");
      return;
    }
    setEnviando(true);
    setError("");
    try {
      await onLogin(email, password);
    } catch (e) {
      setError("Correo o contraseña incorrectos. Verifica los datos e inténtalo nuevamente.");
      setEnviando(false);
    }
  };

  const onKeyDown = (e) => {
    if (e.key === "Enter") entrar();
  };

  return (
    <div className="login-wrap">
      <div className="login-hero">
        <img src={LOGO_FULL} alt="Casa Solar - Energías Limpias" className="login-logo" />
        <p>CRM de ventas y seguimiento</p>
      </div>
      <div className="login-card">
        <label className="field-label">Correo electrónico</label>
        <input className="input" type="email" autoComplete="username" placeholder="correo@empresa.com"
          value={email} onKeyDown={onKeyDown} onChange={e => setEmail(e.target.value)} />
        <label className="field-label">Contraseña</label>
        <input className="input" type="password" autoComplete="current-password" placeholder="Tu contraseña"
          value={password} onKeyDown={onKeyDown} onChange={e => setPassword(e.target.value)} />
        {error && <p className="login-error">{error}</p>}

        <button className="btn-primary" type="button" onClick={entrar} disabled={enviando}>
          {enviando ? "Verificando…" : "Entrar al CRM"}
        </button>
        <p className="login-note">Acceso exclusivo para usuarios autorizados por Casa Solar.</p>
      </div>
    </div>
  );
}

