function PipelineStrip({ contactos }) {
  const max = Math.max(1, ...ESTADOS_CONTACTO.map(e => contactos.filter(c => c.estado === e).length));
  return (
    <div className="pipeline">
      {ESTADOS_CONTACTO.map(estado => {
        const count = contactos.filter(c => c.estado === estado).length;
        const cells = 10;
        const lit = Math.round((count / max) * cells) || (count > 0 ? 1 : 0);
        return (
          <div key={estado} className="pipeline-col">
            <div className="pipeline-count">{count}</div>
            <div className="pipeline-panel">
              {Array.from({ length: cells }).map((_, i) => (
                <div key={i} className={"cell" + (i >= cells - lit ? " lit" : "")} />
              ))}
            </div>
            <div className="pipeline-label">{estado}</div>
          </div>
        );
      })}
    </div>
  );
}

function RouteCalculator({ cotizaciones, currentUser, onUpdateCotizacion }) {
  const [warehouse, setWarehouse] = useState("quetzaltenango");
  const [destination, setDestination] = useState("");
  const [address, setAddress] = useState({ departamento: "Quetzaltenango", municipio: "", lugar: "", zona: "", via: "", nomenclatura: "", casa: "", referencia: "" });
  const [roundTrip, setRoundTrip] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState("");
  const [calculating, setCalculating] = useState(false);
  const [selectedQuoteId, setSelectedQuoteId] = useState("");
  const [attachedMessage, setAttachedMessage] = useState("");
  const [pendingSaved, setPendingSaved] = useState(false);
  const visibleQuotes = currentUser.rol === "Jefe" ? cotizaciones : cotizaciones.filter(item => item.vendedor === currentUser.nombre);

  const geocode = async (query) => {
    const url = `https://nominatim.openstreetmap.org/search?format=json&countrycodes=gt&limit=1&q=${encodeURIComponent(query)}`;
    const response = await fetch(url, { headers: { Accept: "application/json" } });
    if (!response.ok) throw new Error("No se pudo consultar la ubicación.");
    const data = await response.json();
    if (!data?.length) throw new Error(`No encontramos la dirección: ${query}`);
    return { lat: Number(data[0].lat), lon: Number(data[0].lon), name: data[0].display_name };
  };
  const geocodeCandidates = async (queries) => {
    for (const query of [...new Set(queries.filter(Boolean))]) {
      try { return await geocode(query); } catch { /* intentar una dirección menos específica */ }
    }
    throw new Error("No encontramos la ubicación. Revisa principalmente el municipio y departamento o agrega una referencia conocida.");
  };
  const setAddressPart = (key, value) => setAddress(previous => ({ ...previous, [key]: value }));
  const addressParts = [address.casa, address.nomenclatura, address.via, address.zona && `Zona ${String(address.zona).replace(/^zona\s*/i, "")}`, address.lugar, address.municipio, address.departamento].filter(Boolean);
  const fullDestination = addressParts.join(", ");
  const transportFromResult = () => ({
    id: uid(), productoId: "transporte_ruta", productoNombre: "Transporte", descripcion: "Transporte", tamano: "",
    cantidad: 1, precioLista: result.cost, precioUnitario: result.cost,
    ruta: { origen: WAREHOUSES[warehouse].address, destino: result.target.name, direccionIngresada: fullDestination, referencia: address.referencia, kilometros: result.chargedKm, distanciaUnaVia: result.oneWayKm, idaYRegreso: roundTrip, tarifaKm: TRANSPORT_RATE },
  });

  const attachTransport = () => {
    if (!result || !selectedQuoteId) return;
    const quote = cotizaciones.find(item => item.id === selectedQuoteId);
    if (!quote) return setAttachedMessage("No encontramos la cotización seleccionada.");
    const transportItem = transportFromResult();
    const items = [...(quote.items || []), transportItem];
    const total = items.reduce((sum, item) => sum + Number(item.cantidad || 0) * Number(item.precioUnitario || 0), 0);
    const updated = { ...quote, items, total };
    if (quote.descuentoAutorizado) {
      updated.totalOriginal = total;
      updated.descuentoAutorizado = null;
      updated.descuentoSolicitud = null;
      updated.descuentoHistorial = [...(quote.descuentoHistorial || []), { accion: "Invalidado al agregar transporte", fecha: new Date().toISOString(), usuario: currentUser.nombre, email: currentUser.email || "" }];
    }
    onUpdateCotizacion(updated);
    setAttachedMessage(`Transporte agregado a ${quote.numero || "la cotización"}.`);
    setSelectedQuoteId("");
  };
  const saveForNextQuote = () => {
    if (!result) return;
    saveDraft(`casasolar:transportePendiente:${currentUser.nombre}`, transportFromResult());
    setPendingSaved(true);
    setAttachedMessage("Transporte guardado. Aparecerá al crear tu próxima cotización.");
  };

  const calculate = async () => {
    if (!address.municipio.trim() || !address.departamento) return setError("Selecciona el departamento y escribe el municipio del cliente.");
    setCalculating(true); setError(""); setResult(null);
    try {
      const warehouseQueries = [WAREHOUSES[warehouse].address, ...(WAREHOUSES[warehouse].searchQueries || [])];
      const destinationQueries = [
        `${[address.referencia, ...addressParts].filter(Boolean).join(", ")}, Guatemala`,
        `${fullDestination}, Guatemala`,
        `${[address.via, address.zona && `Zona ${address.zona}`, address.lugar, address.municipio, address.departamento].filter(Boolean).join(", ")}, Guatemala`,
        `${[address.lugar, address.municipio, address.departamento].filter(Boolean).join(", ")}, Guatemala`,
        `${address.municipio}, ${address.departamento}, Guatemala`,
      ];
      const [origin, target] = await Promise.all([geocodeCandidates(warehouseQueries), geocodeCandidates(destinationQueries)]);
      const routeUrl = `https://router.project-osrm.org/route/v1/driving/${origin.lon},${origin.lat};${target.lon},${target.lat}?overview=false&steps=false`;
      const routeResponse = await fetch(routeUrl);
      const routeData = await routeResponse.json();
      if (!routeResponse.ok || routeData.code !== "Ok" || !routeData.routes?.length) throw new Error("No se pudo calcular una ruta vehicular entre esos puntos.");
      const oneWayKm = routeData.routes[0].distance / 1000;
      const chargedKm = oneWayKm * (roundTrip ? 2 : 1);
      setResult({ origin, target, oneWayKm, chargedKm, cost: chargedKm * TRANSPORT_RATE });
      setPendingSaved(false); setAttachedMessage("");
    } catch (reason) {
      setError(reason?.message || "No pudimos calcular la ruta. Revisa la dirección e inténtalo de nuevo.");
    } finally { setCalculating(false); }
  };

  return (
    <div>
      <div className="page-head"><h2>Calculadora de rutas</h2><p>Distancia vehicular en Guatemala y costo de transporte a Q 7.50 por kilómetro.</p></div>
      <div className="route-layout">
        <div className="section-card route-form">
          <label className="field-label">Punto de salida</label>
          <select className="input" value={warehouse} onChange={e => setWarehouse(e.target.value)}>
            {Object.entries(WAREHOUSES).map(([id, item]) => <option key={id} value={id}>{item.label}</option>)}
          </select>
          <div className="address-preview"><MapPin size={16} /><span>{WAREHOUSES[warehouse].address}</span></div>
          <h3 className="route-address-title">Dirección del cliente</h3>
          <div className="route-address-grid">
            <label><span className="field-label">Departamento *</span><select className="input" value={address.departamento} onChange={e => setAddressPart("departamento", e.target.value)}>{GUATEMALA_DEPARTMENTS.map(item => <option key={item}>{item}</option>)}</select></label>
            <label><span className="field-label">Municipio *</span><input className="input" value={address.municipio} onChange={e => setAddressPart("municipio", e.target.value)} placeholder="Ej. Cobán" /></label>
            <label><span className="field-label">Aldea, caserío, colonia o residencial</span><input className="input" value={address.lugar} onChange={e => setAddressPart("lugar", e.target.value)} placeholder="Ej. Aldea Chivencorral" /></label>
            <label><span className="field-label">Zona</span><input className="input" value={address.zona} onChange={e => setAddressPart("zona", e.target.value)} placeholder="Ej. 3" /></label>
            <label><span className="field-label">Calle, avenida, carretera o callejón</span><input className="input" value={address.via} onChange={e => setAddressPart("via", e.target.value)} placeholder="Ej. 4a calle / Callejón Los Pinos" /></label>
            <label><span className="field-label">Nomenclatura</span><input className="input" value={address.nomenclatura} onChange={e => setAddressPart("nomenclatura", e.target.value)} placeholder="Ej. 8-25" /></label>
            <label><span className="field-label">Casa, lote o número</span><input className="input" value={address.casa} onChange={e => setAddressPart("casa", e.target.value)} placeholder="Ej. Casa 12 / Lote 5" /></label>
            <label><span className="field-label">Referencia conocida</span><input className="input" value={address.referencia} onChange={e => { setAddressPart("referencia", e.target.value); setDestination(e.target.value); }} placeholder="Ej. Frente a iglesia o escuela" /></label>
          </div>
          <div className="address-preview"><MapPin size={16} /><span>{fullDestination || "Completa la dirección del cliente"}</span></div>
          <label className="roundtrip-check"><input type="checkbox" checked={roundTrip} onChange={e => setRoundTrip(e.target.checked)} /> Calcular ida y regreso</label>
          {error && <div className="route-error">{error}</div>}
          <button className="btn-primary" onClick={calculate} disabled={calculating}>{calculating ? "Calculando ruta…" : <><Calculator size={16} /> Calcular distancia y costo</>}</button>
        </div>
        <div className="section-card route-result">
          {!result ? <div className="route-empty"><MapPin size={28} /><strong>El resultado aparecerá aquí</strong><span>Usaremos la ruta vehicular disponible, no la distancia en línea recta.</span></div> : <>
            <div className="route-result-head"><span>RESULTADO</span><strong>{roundTrip ? "Ida y regreso" : "Solo ida"}</strong></div>
            <div className="route-metric"><span>Distancia de una vía</span><strong>{result.oneWayKm.toFixed(1)} km</strong></div>
            <div className="route-metric"><span>Kilómetros a cobrar</span><strong>{result.chargedKm.toFixed(1)} km</strong></div>
            <div className="route-formula">{result.chargedKm.toFixed(1)} km × Q {TRANSPORT_RATE.toFixed(2)}</div>
            <div className="route-total"><span>Costo de transporte</span><strong>{fmtMoney(result.cost)}</strong></div>
            <small>Destino encontrado: {result.target.name}</small>
            <small className="route-match-warning">Verifica que el lugar encontrado corresponda al municipio, zona o aldea del cliente antes de adjuntar el transporte.</small>
            <button className="btn-primary route-save-next" onClick={saveForNextQuote} disabled={pendingSaved}><ShoppingCart size={16} /> {pendingSaved ? "Guardado para próxima cotización" : "Guardar para la próxima cotización"}</button>
            <div className="route-attach">
              <label className="field-label">¿Deseas adjuntarlo a una cotización?</label>
              <select className="input" value={selectedQuoteId} onChange={e => { setSelectedQuoteId(e.target.value); setAttachedMessage(""); }}>
                <option value="">No adjuntar · Solo calcular</option>
                {visibleQuotes.map(quote => <option key={quote.id} value={quote.id}>{quote.numero || "Sin número"} · {quote.contactoNombre || "Sin contacto"}</option>)}
              </select>
              {selectedQuoteId && <button className="btn-primary" onClick={attachTransport}><Plus size={16} /> Agregar como transporte</button>}
              {attachedMessage && <p className="form-success">{attachedMessage}</p>}
            </div>
          </>}
        </div>
      </div>
      <p className="route-note">Cálculo orientativo basado en rutas de OpenStreetMap. Confirma accesos, desvíos, peajes y condiciones de carretera antes de cerrar la cotización.</p>
    </div>
  );
}

function Dashboard({ contactos, cotizaciones, seguimientos, currentUser, vendedores }) {
  const misContactos = currentUser.rol === "Jefe" ? contactos : contactos.filter(c => c.vendedor === currentUser.nombre);
  const misCot = currentUser.rol === "Jefe" ? cotizaciones : cotizaciones.filter(c => c.vendedor === currentUser.nombre);
  const hoy = todayISO();
  const nuevosHoy = misContactos.filter(c => c.fecha === hoy).length;
  const ganados = misContactos.filter(c => c.estado === "Ganado").length;
  const total = misContactos.length;
  const tasaCierre = total ? Math.round((ganados / total) * 100) : 0;
  const montoCotizado = misCot.reduce((s, c) => s + (c.total || 0), 0);
  const seguimientosPendientes = (currentUser.rol === "Jefe" ? seguimientos : seguimientos.filter(s => s.vendedor === currentUser.nombre))
    .filter(s => s.proximoSeguimiento && s.proximoSeguimiento <= hoy);

  const porVendedor = vendedores.map(v => ({
    nombre: v.nombre,
    contactos: contactos.filter(c => c.vendedor === v.nombre).length,
    cotizaciones: cotizaciones.filter(c => c.vendedor === v.nombre).length,
    ganados: contactos.filter(c => c.vendedor === v.nombre && c.estado === "Ganado").length,
  }));

  return (
    <div>
      <div className="page-head">
        <h2>Hola, {currentUser.nombre.split(" ")[0]}</h2>
        <p>{currentUser.rol === "Jefe" ? "Vista general de todo el equipo de ventas." : "Este es tu resumen del día."}</p>
      </div>

      <div className="kpi-grid">
        <div className="kpi-card">
          <div className="kpi-label">Contactos totales</div>
          <div className="kpi-value">{total}</div>
        </div>
        <div className="kpi-card">
          <div className="kpi-label">Nuevos hoy</div>
          <div className="kpi-value">{nuevosHoy}</div>
        </div>
        <div className="kpi-card">
          <div className="kpi-label">Cotizado (Q)</div>
          <div className="kpi-value">{fmtMoney(montoCotizado)}</div>
        </div>
        <div className="kpi-card">
          <div className="kpi-label">Tasa de cierre</div>
          <div className="kpi-value">{tasaCierre}%</div>
        </div>
      </div>

      <div className="section-card">
        <h3>Embudo de ventas</h3>
        <PipelineStrip contactos={misContactos} />
      </div>

      {seguimientosPendientes.length > 0 && (
        <div className="section-card">
          <h3><Clock size={15} style={{ verticalAlign: -2 }} /> Seguimientos pendientes ({seguimientosPendientes.length})</h3>
          <div className="mini-list">
            {seguimientosPendientes.slice(0, 6).map(s => (
              <div key={s.id} className="mini-row">
                <span>{s.contactoNombre}</span>
                <span className="muted">{s.tipo}</span>
                <span className="muted">{fmtDate(s.proximoSeguimiento)}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {currentUser.rol === "Jefe" && porVendedor.length > 0 && (
        <div className="section-card">
          <h3>Desempeño por vendedor</h3>
          <table className="table">
            <thead><tr><th>Vendedor</th><th>Contactos</th><th>Cotizaciones</th><th>Ganados</th></tr></thead>
            <tbody>
              {porVendedor.map(v => (
                <tr key={v.nombre}><td>{v.nombre}</td><td>{v.contactos}</td><td>{v.cotizaciones}</td><td>{v.ganados}</td></tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function ContactModal({ initial, vendedores, currentUser, onSave, onClose }) {
  const draftKey = `casasolar:draft:contacto:${initial?.id || "nuevo"}:${currentUser.uid || currentUser.email}`;
  const defaultForm = initial || {
    nombre: "", telefono: "", email: "", canal: "Llamada entrante",
    dpi: "", nit: "", direccion: "", departamento: "",
    productoInteres: CATALOGO[0].id, estado: "Nuevo",
    vendedor: currentUser.rol === "Vendedor" ? currentUser.nombre : (vendedores[0]?.nombre || currentUser.nombre),
    permisoPromociones: "Pendiente de confirmar", notas: "", fecha: todayISO(),
  };
  const [form, setForm] = useState(() => readDraft(draftKey, defaultForm));
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));
  useEffect(() => { saveDraft(draftKey, form); }, [draftKey, form]);
  const saveContact = () => { clearDraft(draftKey); onSave(form); };

  return (
    <div className="modal-overlay">
      <div className="modal" onClick={e => e.stopPropagation()}>
        <div className="modal-head">
          <div><h3>{initial ? "Editar contacto" : "Nuevo contacto"}</h3><small className="draft-note">Borrador guardado automáticamente</small></div>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>
        <div className="modal-body">
          <label className="field-label">Nombre</label>
          <input className="input" value={form.nombre} onChange={e => set("nombre", e.target.value)} placeholder="Nombre del cliente" />
          <div className="row-2">
            <div>
              <label className="field-label">Teléfono</label>
              <input className="input" value={form.telefono} onChange={e => set("telefono", e.target.value)} placeholder="5555-5555" />
            </div>
            <div>
              <label className="field-label">Email</label>
              <input className="input" value={form.email} onChange={e => set("email", e.target.value)} placeholder="correo@ejemplo.com" />
            </div>
          </div>
          <div className="row-2">
            <div>
              <label className="field-label">DPI / CUI</label>
              <input className="input" value={form.dpi || ""} onChange={e => set("dpi", e.target.value)} placeholder="0000 00000 0000" />
            </div>
            <div>
              <label className="field-label">NIT</label>
              <input className="input" value={form.nit || ""} onChange={e => set("nit", e.target.value)} placeholder="C/F" />
            </div>
          </div>
          <div className="row-2">
            <div>
              <label className="field-label">Departamento</label>
              <input className="input" value={form.departamento || ""} onChange={e => set("departamento", e.target.value)} placeholder="Quetzaltenango" />
            </div>
            <div>
              <label className="field-label">Municipio</label>
              <input className="input" value={form.municipio || ""} onChange={e => set("municipio", e.target.value)} placeholder="Quetzaltenango" />
            </div>
          </div>
          <label className="field-label">Dirección</label>
          <input className="input" value={form.direccion || ""} onChange={e => set("direccion", e.target.value)} placeholder="Dirección del cliente" />
          <div className="row-2">
            <div>
              <label className="field-label">Canal de contacto</label>
              <select className="input" value={form.canal} onChange={e => set("canal", e.target.value)}>
                {CANALES.map(c => <option key={c.id} value={c.id}>{c.id}</option>)}
              </select>
            </div>
            <div>
              <label className="field-label">Producto de interés</label>
              <select className="input" value={form.productoInteres} onChange={e => set("productoInteres", e.target.value)}>
                {CATALOGO.map(p => <option key={p.id} value={p.id}>{p.nombre}</option>)}
              </select>
            </div>
          </div>
          <div className="row-2">
            <div>
              <label className="field-label">Estado</label>
              <select className="input" value={form.estado} onChange={e => set("estado", e.target.value)}>
                {ESTADOS_CONTACTO.map(e => <option key={e} value={e}>{e}</option>)}
              </select>
            </div>
            <div>
              <label className="field-label">Vendedor asignado</label>
              <select className="input" disabled={currentUser.rol !== "Jefe"} value={form.vendedor} onChange={e => set("vendedor", e.target.value)}>
                {vendedores.map(v => <option key={v.id} value={v.nombre}>{v.nombre}</option>)}
              </select>
            </div>
          </div>
          <label className="field-label">Permiso para recibir promociones</label>
          <select className="input" value={form.permisoPromociones || "Pendiente de confirmar"} onChange={e => set("permisoPromociones", e.target.value)}>
            <option>Pendiente de confirmar</option>
            <option>Acepta promociones</option>
            <option>No contactar</option>
          </select>
          <label className="field-label">Notas</label>
          <textarea className="input" rows={3} value={form.notas} onChange={e => set("notas", e.target.value)} placeholder="Detalles de la necesidad del cliente…" />
        </div>
        <div className="modal-foot">
          <button className="btn-ghost" onClick={onClose}>Cerrar</button>
          <button className="btn-primary" disabled={!form.nombre.trim()} onClick={saveContact}>Guardar contacto</button>
        </div>
      </div>
    </div>
  );
}

function CotizacionModal({ contactos, initialContactId, vendedor, initial, onSave, onClose }) {
  const draftKey = `casasolar:draft:cotizacion:${initial?.id || initialContactId || "nueva"}`;
  const pendingTransportKey = `casasolar:transportePendiente:${vendedor}`;
  const savedDraft = useMemo(() => readDraft(draftKey, {}), [draftKey]);
  const [contactoId, setContactoId] = useState(savedDraft.contactoId || initial?.contactoId || initialContactId || (contactos[0]?.id || ""));
  const [items, setItems] = useState(() => (savedDraft.items || initial?.items || []).map(item => ({ ...item, id: item.id || uid() })));
  const [prod, setProd] = useState(savedDraft.prod || CATALOGO[0].id);
  const [categoria, setCategoria] = useState(savedDraft.categoria || categoriaProducto(savedDraft.prod || CATALOGO[0].id));
  const [descripcion, setDescripcion] = useState(savedDraft.descripcion || CATALOGO[0].nombre);
  const [tamano, setTamano] = useState(savedDraft.tamano || "");
  const [altura, setAltura] = useState(savedDraft.altura || "");
  const [compatibilidad, setCompatibilidad] = useState(savedDraft.compatibilidad || "");
  const [cant, setCant] = useState(savedDraft.cant || 1);
  const [precioLista, setPrecioLista] = useState(savedDraft.precioLista ?? "");
  const [precio, setPrecio] = useState(savedDraft.precio ?? "");
  const [notas, setNotas] = useState(savedDraft.notas ?? initial?.notas ?? "");
  const [estado, setEstado] = useState(savedDraft.estado || initial?.estado || "Pendiente");
  const [promocion, setPromocion] = useState(savedDraft.promocion ?? initial?.promocion ?? "");
  const [garantiaAnios, setGarantiaAnios] = useState(savedDraft.garantiaAnios ?? initial?.garantiaAnios ?? String(initial?.garantia || "").replace(/[^0-9]/g, ""));
  const [editingItemId, setEditingItemId] = useState(savedDraft.editingItemId || null);
  const [pendingTransport, setPendingTransport] = useState(() => initial ? null : readDraft(pendingTransportKey, null));
  const clienteSeleccionado = contactos.find(c => c.id === contactoId);
  const esEstructura = String(prod).startsWith("estructura_");

  const total = items.reduce((s, it) => s + it.cantidad * it.precioUnitario, 0);
  useEffect(() => {
    saveDraft(draftKey, { contactoId, items, notas, estado, promocion, garantiaAnios, prod, categoria, descripcion, tamano, altura, compatibilidad, cant, precioLista, precio, editingItemId });
  }, [draftKey, contactoId, items, notas, estado, promocion, garantiaAnios, prod, categoria, descripcion, tamano, altura, compatibilidad, cant, precioLista, precio, editingItemId]);
  const saveQuote = () => {
    clearDraft(draftKey);
    const commercial = { promocion: promocion.trim(), garantiaAnios: Number(garantiaAnios) || "", garantia: garantiaAnios ? `${Number(garantiaAnios)} años` : "" };
    onSave(initial ? { ...initial, contactoId, items, total, estado, notas, ...commercial } : { contactoId, items, total, estado, notas, ...commercial, vendedor, fecha: todayISO(), vigenciaDias: 30, ivaIncluido: true, envios: [] });
  };

  const addItem = () => {
    const p = Number(precio);
    if (precio === "" || Number.isNaN(p) || p < 0) return;
    const nextItem = {
      id: uid(), productoId: prod, productoNombre: productoNombre(prod), categoria,
      descripcion: descripcion.trim() || productoNombre(prod), tamano: tamano.trim(),
      altura: altura.trim(), compatibilidad: compatibilidad.trim(),
      cantidad: Number(cant) || 1, precioLista: Number(precioLista) || p, precioUnitario: p,
    };
    setItems(list => editingItemId
      ? list.map(item => item.id === editingItemId ? { ...nextItem, id: editingItemId } : item)
      : [...list, nextItem]);
    setPrecio(""); setPrecioLista(""); setTamano(""); setAltura(""); setCompatibilidad(""); setCant(1);
    setDescripcion(productoNombre(prod)); setEditingItemId(null);
  };

  const editItem = (item) => {
    setEditingItemId(item.id); setProd(item.productoId || CATALOGO[0].id); setCategoria(item.categoria || categoriaProducto(item.productoId));
    setDescripcion(nombreItem(item));
    setTamano(item.tamano || ""); setCant(item.cantidad || 1);
    setAltura(item.altura || ""); setCompatibilidad(item.compatibilidad || "");
    setPrecioLista(item.precioLista ?? item.precioUnitario ?? ""); setPrecio(item.precioUnitario ?? item.precio ?? "");
  };
  const addPendingTransport = () => {
    if (!pendingTransport) return;
    setItems(list => [...list, { ...pendingTransport, id: pendingTransport.id || uid(), descripcion: "Transporte", tamano: "" }]);
    clearDraft(pendingTransportKey);
    setPendingTransport(null);
  };

  return (
    <div className="modal-overlay">
      <div className="modal quote-modal" onClick={e => e.stopPropagation()}>
        <div className="modal-head">
          <div><h3>{initial ? `Editar cotización ${initial.numero || "sin número"}` : "Nueva cotización"}</h3><small className="draft-note">Borrador guardado automáticamente</small></div>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>
        <div className="modal-body">
          <label className="field-label">Contacto</label>
          <select className="input" value={contactoId} onChange={e => setContactoId(e.target.value)}>
            {contactos.map(c => <option key={c.id} value={c.id}>{c.nombre}</option>)}
          </select>
          {clienteSeleccionado && (
            <div className="client-preview">
              <span><strong>Teléfono:</strong> {clienteSeleccionado.telefono || "Sin registrar"}</span>
              <span><strong>Correo:</strong> {clienteSeleccionado.email || "Sin registrar"}</span>
              <span><strong>NIT:</strong> {clienteSeleccionado.nit || "C/F"}</span>
              <span><strong>Departamento:</strong> {clienteSeleccionado.departamento || "Sin registrar"}</span>
              <span className="full"><strong>Dirección:</strong> {clienteSeleccionado.direccion || "Sin registrar"}</span>
            </div>
          )}

          {pendingTransport && <div className="pending-transport-card"><div><ShoppingCart size={17} /><span><strong>Transporte calculado pendiente</strong><small>Importe: {fmtMoney(pendingTransport.precioUnitario)}. Los kilómetros y la tarifa permanecerán internos.</small></span></div><button className="btn-primary" onClick={addPendingTransport}><Plus size={16} /> Agregar a esta cotización</button></div>}

          <label className="field-label">Agregar producto o servicio</label>
          <div className="item-row quote-item-grid">
            <select className="input" value={prod} onChange={e => { const next = e.target.value; setProd(next); setCategoria(categoriaProducto(next)); setDescripcion(productoNombre(next)); if (!String(next).startsWith("estructura_")) { setAltura(""); setCompatibilidad(""); } }}>
              {CATALOGO.map(p => <option key={p.id} value={p.id}>{p.nombre}</option>)}
            </select>
            <input className="input" value={descripcion} onChange={e => setDescripcion(e.target.value)} placeholder="Descripción específica" />
            <input className="input" value={tamano} onChange={e => setTamano(e.target.value)} placeholder="Tamaño (ej. 25 tubos / 300 L)" />
            <input className="input qty" type="number" min="1" value={cant} onChange={e => setCant(e.target.value)} placeholder="Cant." />
            <input className="input price" type="number" min="0" value={precioLista} onChange={e => setPrecioLista(e.target.value)} placeholder="Precio lista Q" />
            <input className="input price" type="number" min="0" value={precio} onChange={e => setPrecio(e.target.value)} placeholder="Precio cotizado Q" />
            <button className="btn-ghost small" onClick={addItem}>{editingItemId ? <><CheckCircle2 size={14} /> Actualizar</> : <><Plus size={14} /> Agregar</>}</button>
          </div>
          <div className="quote-category-row"><label><span className="field-label">Categoría del producto</span><select className="input" value={categoria} onChange={e => setCategoria(e.target.value)}>{CATEGORIAS_PRODUCTO.map(item => <option key={item}>{item}</option>)}</select></label><p>Escribe en “Descripción específica” el nombre exacto del producto; así aparecerá individualmente en el reporte.</p></div>
          {esEstructura && <div className="row-2 structure-fields"><div><label className="field-label">Altura de la estructura</label><input className="input" value={altura} onChange={e => setAltura(e.target.value)} placeholder="Ej. 1.50 metros" /></div><div><label className="field-label">Compatible con / tamaño requerido</label><input className="input" value={compatibilidad} onChange={e => setCompatibilidad(e.target.value)} placeholder="Ej. CSP30, 30 tubos o depósito de 2,500 L" /></div></div>}

          {items.length > 0 && (
            <table className="table small">
              <thead><tr><th>Producto</th><th>Categoría</th><th>Tamaño</th><th>Cant.</th><th>Precio</th><th>Subtotal</th><th></th></tr></thead>
              <tbody>
                {items.map(it => (
                  <tr key={it.id}>
                    <td>{nombreItem(it)}</td>
                    <td>{it.categoria || categoriaProducto(it.productoId)}</td>
                    <td>{[it.tamano, it.altura && `Altura: ${it.altura}`, it.compatibilidad && `Para: ${it.compatibilidad}`].filter(Boolean).join(" · ") || "—"}</td>
                    <td>{it.cantidad}</td>
                    <td>{fmtMoney(it.precioUnitario)}</td>
                    <td>{fmtMoney(it.cantidad * it.precioUnitario)}</td>
                    <td><div className="row"><button className="icon-btn" title="Editar producto" onClick={() => editItem(it)}><Edit3 size={14} /></button><button className="icon-btn" title="Eliminar producto" onClick={() => setItems(l => l.filter(x => x.id !== it.id))}><Trash2 size={14} /></button></div></td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}

          <div className="total-line">Total: <strong>{fmtMoney(total)}</strong></div>

          <div className="row-2">
            <div>
              <label className="field-label">Estado</label>
              <select className="input" value={estado} onChange={e => setEstado(e.target.value)}>
                {ESTADOS_COTIZACION.map(e => <option key={e} value={e}>{e}</option>)}
              </select>
            </div>
          </div>
          <div className="row-2">
            <div><label className="field-label">Promoción aplicada</label><input className="input" value={promocion} onChange={e => setPromocion(e.target.value)} placeholder="Ej. Promoción de agosto / Precio especial" /></div>
            <div><label className="field-label">Años de garantía del producto</label><input className="input" type="number" min="0" value={garantiaAnios} onChange={e => setGarantiaAnios(e.target.value)} placeholder="Ej. 9" /></div>
          </div>
          <label className="field-label">Notas</label>
          <textarea className="input" rows={2} value={notas} onChange={e => setNotas(e.target.value)} />
        </div>
        <div className="modal-foot">
          <button className="btn-ghost" onClick={onClose}>Cerrar</button>
          <button className="btn-primary" disabled={!contactoId || items.length === 0}
            onClick={saveQuote}>
            {initial ? "Guardar cambios" : "Guardar cotización"}
          </button>
        </div>
      </div>
    </div>
  );
}

function SeguimientoModal({ contactos, initialContactId, vendedor, onSave, onClose }) {
  const [contactoId, setContactoId] = useState(initialContactId || (contactos[0]?.id || ""));
  const [tipo, setTipo] = useState("Llamada");
  const [notas, setNotas] = useState("");
  const [proximo, setProximo] = useState("");
  const [guardando, setGuardando] = useState(false);
  const save = async () => {
    if (!contactoId || !notas.trim() || guardando) return;
    setGuardando(true);
    try {
      await onSave({ contactoId, tipo, notas: notas.trim(), proximoSeguimiento: proximo, vendedor, fecha: todayISO(), fechaHora: new Date().toISOString() });
    } finally {
      setGuardando(false);
    }
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal" onClick={e => e.stopPropagation()}>
        <div className="modal-head">
          <h3>Nuevo seguimiento</h3>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>
        <div className="modal-body">
          <label className="field-label">Contacto</label>
          <select className="input" value={contactoId} onChange={e => setContactoId(e.target.value)}>
            {contactos.map(c => <option key={c.id} value={c.id}>{c.nombre}</option>)}
          </select>
          <label className="field-label">Tipo</label>
          <select className="input" value={tipo} onChange={e => setTipo(e.target.value)}>
            {TIPOS_SEGUIMIENTO.map(t => <option key={t} value={t}>{t}</option>)}
          </select>
          <label className="field-label">Notas</label>
          <textarea className="input" rows={3} value={notas} onChange={e => setNotas(e.target.value)} placeholder="¿Qué se conversó?" />
          <label className="field-label">Próximo seguimiento (opcional)</label>
          <input className="input" type="date" value={proximo} onChange={e => setProximo(e.target.value)} />
        </div>
        <div className="modal-foot">
          <button className="btn-ghost" onClick={onClose}>Cancelar</button>
          <button className="btn-primary" disabled={!contactoId || !notas.trim() || guardando} onClick={save}>
            {guardando ? "Guardando en Firebase…" : "Guardar seguimiento"}
          </button>
        </div>
      </div>
    </div>
  );
}

function OrderFormModal({ cotizacion, contacto, currentUser, vendedores = [], onClose, onSave, onGenerate, onAdvance, advanceLabel }) {
  const draftKey = `casasolar:draft:orden:${cotizacion.id || cotizacion.numero}`;
  const defaultForm = {
    tipoOrden: "Calentadores",
    tipoEvaluacion: "Visita por llamada", fechaVisitaTecnica: "", horaVisitaTecnica: "", visitaTecnicaProgramada: false, visitaTecnicaProgramadaEn: "",
    fechaInstalacion: "", horario: "Mañana", direccion: contacto?.direccion || "",
    departamento: contacto?.departamento || "", telefono: contacto?.telefono || "",
    dpi: contacto?.dpi || "", nit: contacto?.nit || "", niveles: "1", materialTecho: "Lámina", tipoTecho: "",
    tuberiaCaliente: "Sí", tuberiaFria: "Sí", presionAgua: "Media",
    medidaTuberiaCaliente: "CPVC 1/2 pulgada", medidaTuberiaFria: "PVC 1/2 pulgada", otroCalentador: "No",
    detalleOtroCalentador: "", variacionPresion: "No", detalleVariacionPresion: "",
    instalacionesAdicionales: "", distanciaAdicional: "",
    bomba: "No", deposito: "Sí", alturaDeposito: "", conectaDeposito: "Sí",
    gradas: "Sí", entraCamion: "Sí", formaPago: "Transferencia",
    estadoPago: "Pendiente", abono: "", saldo: String(cotizacion.total || ""), promocion: cotizacion.promocion || "",
    garantia: cotizacion.garantia || "", observaciones: cotizacion.notas || "",
    evidenciasFotograficas: "",
    tipoServicio: "Mantenimiento", equipoExistente: "", fallaReportada: "", servicioRequerido: "", materialesServicio: "",
    motivoRevision: "", diagnosticoPreliminar: "", medicionesTecnicas: "", accesoTecho: "Sí", riesgosDetectados: "",
    areaIluminar: "", alturaInstalacionLuz: "", cantidadLuminarias: "", potenciaLuminaria: "", ubicacionPanelSolar: "", horasIluminacion: "",
    tecnicoAsignadoEmail: "", tecnicoAsignadoNombre: "", departamentoVisita: contacto?.departamento || "",
    evaluacionTecnicaEstado: "Pendiente", evaluacionTecnicaInforme: "", evaluacionAprobadaCliente: "Pendiente",
    evaluacionAprobadaPor: "", evaluacionAprobadaEn: "", ordenFinalGenerada: false, ordenFinalGeneradaEn: "",
    estadoInstalacion: "Pendiente de programación", estadoBodega: "Pendiente",
    informeInstalacion: { recibidoPor: "", detalle: "", evidencias: "", fechaHora: "", lugar: "", coordenadas: "", tecnicoNombre: "", tecnicoEmail: "", resultado: "" },
    garantiaSolicitada: "No", garantiaMotivo: "", garantiaDetalleFalla: "", garantiaFechaSolicitud: "",
    garantiaJefeTecnico: "Pendiente", garantiaJefeTecnicoPor: "", garantiaJefeTecnicoFecha: "",
    garantiaJefatura: "Pendiente", garantiaJefaturaPor: "", garantiaJefaturaFecha: "",
    ...(cotizacion.ordenPedido || {}),
  };
  const [form, setForm] = useState(() => {
    const draft = readDraft(draftKey, defaultForm);
    if (draft.tipoEvaluacion === "Visita presencial") draft.tipoEvaluacion = "Visita técnica presencial";
    if (!["CPVC 1/2 pulgada", "CPVC 3/4 pulgada", "Otra"].includes(draft.medidaTuberiaCaliente)) draft.medidaTuberiaCaliente = "CPVC 1/2 pulgada";
    if (!["PVC 1/2 pulgada", "PVC 3/4 pulgada", "Otra"].includes(draft.medidaTuberiaFria)) draft.medidaTuberiaFria = "PVC 1/2 pulgada";
    return draft;
  });
  const set = (key, value) => setForm(prev => ({
    ...prev, [key]: value,
    ...(["fechaVisitaTecnica", "horaVisitaTecnica", "tipoEvaluacion"].includes(key) ? { visitaTecnicaProgramada: false, visitaTecnicaProgramadaEn: "" } : {}),
    ...(key === "estadoPago" && value === "Abonado" && !prev.fechaAnticipo ? { fechaAnticipo: todayISO() } : {}),
    ...(key === "estadoPago" && value === "Cancelado" && !prev.fechaCancelado ? { fechaCancelado: todayISO(), saldo: "0" } : {}),
    ...(key === "garantiaSolicitada" && value === "Sí" && !prev.garantiaFechaSolicitud ? { garantiaFechaSolicitud: todayISO() } : {}),
  }));
  useEffect(() => { saveDraft(draftKey, form); }, [draftKey, form]);
  const generateOrder = () => {
    const finalForm = { ...form, ordenFinalGenerada: true, ordenFinalGeneradaEn: new Date().toISOString() };
    clearDraft(draftKey);
    onGenerate(finalForm);
  };
  const saveOrder = () => { clearDraft(draftKey); onSave?.(form); };
  const isTechnician = currentUser?.rol === "Técnico";
  const isTechnicalArea = ["Técnico", "Jefe técnico"].includes(currentUser?.rol);
  const canAssignTechnician = currentUser?.rol === "Jefe técnico" || ["leyla.flores@gmail.com", "ligiaeugeniamolina@gmail.com"].includes(String(currentUser?.email || "").toLowerCase());
  const technicians = vendedores.filter(user => ["Técnico", "Jefe técnico"].includes(user.rol));
  const assignedToCurrentUser = String(form.tecnicoAsignadoEmail || "").toLowerCase() === String(currentUser?.email || "").toLowerCase();
  const canCompleteInstallation = assignedToCurrentUser && ["Técnico", "Jefe técnico"].includes(currentUser?.rol);
  const setReport = (key, value) => setForm(prev => ({ ...prev, informeInstalacion: { ...(prev.informeInstalacion || {}), [key]: value } }));
  const registerInstallation = () => {
    const report = form.informeInstalacion || {};
    if (!String(report.recibidoPor || "").trim()) return window.alert("Escribe el nombre de la persona que recibió el equipo.");
    if (!String(report.detalle || "").trim()) return window.alert("Escribe el informe del trabajo realizado.");
    const finish = (coordinates = "", locationStatus = "Ubicación GPS no disponible") => {
      const now = new Date().toISOString();
      setForm(prev => ({
        ...prev,
        estadoInstalacion: "Instalada",
        informeInstalacion: {
          ...(prev.informeInstalacion || {}),
          fechaHora: now,
          lugar: coordinates ? `${prev.direccion || contacto?.direccion || "Dirección registrada"} · GPS confirmado` : (prev.direccion || contacto?.direccion || locationStatus),
          coordenadas: coordinates,
          tecnicoNombre: currentUser.nombre,
          tecnicoEmail: currentUser.email || "",
          resultado: "Instalación realizada",
        },
      }));
      window.alert("Instalación registrada. Presiona Guardar registro para enviarla al historial y a los informes.");
    };
    if (!navigator.geolocation) return finish();
    navigator.geolocation.getCurrentPosition(
      position => finish(`${position.coords.latitude.toFixed(6)}, ${position.coords.longitude.toFixed(6)}`),
      () => finish("", "Ubicación no autorizada por el dispositivo"),
      { enableHighAccuracy: true, timeout: 12000, maximumAge: 0 },
    );
  };
  const isWarrantyBoss = ["leyla.flores@gmail.com", "ligiaeugeniamolina@gmail.com"].includes(String(currentUser?.email || "").toLowerCase());
  const warrantyReady = form.garantiaSolicitada === "Sí" && form.garantiaJefeTecnico === "Aceptada" && form.garantiaJefatura === "Aceptada";
  const warrantyDecision = (area, accepted) => {
    const now = new Date().toISOString();
    if (area === "tecnico") setForm(prev => ({ ...prev, garantiaJefeTecnico: accepted ? "Aceptada" : "No aceptada", garantiaJefeTecnicoPor: currentUser.nombre, garantiaJefeTecnicoFecha: now, ...(accepted ? {} : { garantiaJefatura: "Pendiente", garantiaJefaturaPor: "", garantiaJefaturaFecha: "" }) }));
    else setForm(prev => ({ ...prev, garantiaJefatura: accepted ? "Aceptada" : "No aceptada", garantiaJefaturaPor: currentUser.nombre, garantiaJefaturaFecha: now }));
  };
  const scheduleTechnicalVisit = () => {
    if (!form.fechaVisitaTecnica || !form.horaVisitaTecnica) return window.alert("Selecciona la fecha y la hora de la visita técnica presencial.");
    setForm(prev => ({ ...prev, visitaTecnicaProgramada: true, visitaTecnicaProgramadaEn: new Date().toISOString() }));
    window.alert("Visita técnica presencial programada. Presiona Guardar registro para confirmar los cambios.");
  };
  const technicalEvaluationReady = (form.evaluacionTecnicaEstado === "Realizada" && form.evaluacionAprobadaCliente === "Aprobada")
    || Boolean(form.ordenFinalGenerada || form.fechaInstalacion || form.informeInstalacion?.fechaHora);
  const roleRequiresApprovedEvaluation = role => role === "Técnico";
  const confirmTechnicalEvaluation = () => {
    if (!String(form.evaluacionTecnicaInforme || "").trim()) return window.alert("Escribe el resultado de la evaluación técnica.");
    setForm(prev => ({ ...prev, evaluacionTecnicaEstado: "Realizada", evaluacionTecnicaRealizadaEn: new Date().toISOString(), evaluacionTecnicaRealizadaPor: currentUser.nombre }));
  };
  const approveEvaluation = () => {
    if (form.evaluacionTecnicaEstado !== "Realizada") return window.alert("Primero el técnico debe marcar la evaluación como realizada.");
    if (!String(form.evaluacionAprobadaPor || "").trim()) return window.alert("Escribe el nombre del cliente o responsable que aprobó la evaluación.");
    setForm(prev => ({ ...prev, evaluacionAprobadaCliente: "Aprobada", evaluacionAprobadaEn: new Date().toISOString() }));
  };
  const field = (label, key, type = "text") => (
    <div><label className="field-label">{label}</label><input className="input" type={type} value={form[key]} onChange={e => set(key, e.target.value)} /></div>
  );
  const select = (label, key, options) => (
    <div><label className="field-label">{label}</label><select className="input" value={form[key]} onChange={e => set(key, e.target.value)}>{options.map(o => <option key={o}>{o}</option>)}</select></div>
  );
  return (
    <div className="modal-overlay">
      <div className="modal modal-wide" onClick={e => e.stopPropagation()}>
        <div className="modal-head"><div><h3>Orden de pedido {cotizacion.ordenNumero || ""}</h3><small>Basada en {cotizacion.numero} · {contacto?.nombre}</small><small className="draft-note">Borrador guardado automáticamente</small></div><button className="icon-btn" onClick={onClose}><X size={18} /></button></div>
        <div className="modal-body">
          <label className="field-label">Tipo de orden de pedido</label>
          <select className="input order-type-select" value={form.tipoOrden || "Calentadores"} onChange={e => set("tipoOrden", e.target.value)}><option>Calentadores</option><option>Servicios</option><option>Revisión técnica</option><option>Iluminación</option></select>
          <div className="order-evaluation-summary">
            <div className="order-summary-head"><ClipboardList size={18} /><div><h4>Información para evaluación técnica</h4><p>Datos tomados automáticamente de la cotización.</p></div></div>
            <div className="order-summary-grid">
              <div><span>Cliente</span><strong>{contacto?.nombre || cotizacion.contactoNombre || "Sin registrar"}</strong></div>
              <div><span>Teléfono</span><strong>{contacto?.telefono || "Sin registrar"}</strong></div>
              <div><span>Dirección</span><strong>{contacto?.direccion || "Sin registrar"}</strong></div>
              <div><span>Departamento</span><strong>{contacto?.departamento || "Sin registrar"}</strong></div>
            </div>
            <div className="quoted-equipment"><span>Equipo cotizado</span>{(cotizacion.items || []).map(item => <div key={item.id || `${item.productoId}-${item.descripcion}`}><strong>{item.cantidad || 1} × {nombreItem(item)}</strong>{item.tamano && <small>{item.tamano}</small>}</div>)}</div>
          </div>
          <h4>Tipo de evaluación técnica</h4>
          <div className="evaluation-type-buttons">
            {["Visita por llamada", "Visita por videollamada", "Visita técnica presencial"].map(option => <button type="button" key={option} className={form.tipoEvaluacion === option ? "active" : ""} onClick={() => set("tipoEvaluacion", option)}>{form.tipoEvaluacion === option && <CheckCircle2 size={15} />}{option}</button>)}
          </div>
          <div className="evaluation-route-note"><Send size={15} /><span>{String(form.tipoEvaluacion).includes("presencial") ? "Se enviará al Jefe técnico para asignar y programar al técnico." : "Se enviará directamente a Programación para coordinar la llamada con el cliente."}</span></div>
          <h4>{String(form.tipoEvaluacion).includes("presencial") ? "Asignación de visita presencial" : "Responsable y programación"}</h4>
          <div className="form-grid">
            {field("Departamento de la visita", "departamentoVisita")}
            <div><label className="field-label">Técnico asignado</label><select className="input" disabled={!canAssignTechnician} value={form.tecnicoAsignadoEmail} onChange={e => { const tech = technicians.find(item => item.email === e.target.value); setForm(prev => ({ ...prev, tecnicoAsignadoEmail: e.target.value, tecnicoAsignadoNombre: tech?.nombre || "" })); }}><option value="">Sin asignar</option>{technicians.map(tech => <option key={tech.id || tech.email} value={tech.email}>{tech.nombre}{tech.departamentosCobertura ? ` · ${tech.departamentosCobertura}` : ""}</option>)}</select></div>
            {field(String(form.tipoEvaluacion).includes("presencial") ? "Fecha de visita técnica" : "Fecha de llamada o videollamada", "fechaVisitaTecnica", "date")}
            {String(form.tipoEvaluacion).includes("presencial") && field("Hora de visita técnica", "horaVisitaTecnica", "time")}
          </div>
          {String(form.tipoEvaluacion).includes("presencial") && <div className="evaluation-route-note"><Clock size={15}/><span>{form.visitaTecnicaProgramada ? `Programada para ${form.fechaVisitaTecnica} a las ${form.horaVisitaTecnica}` : "Selecciona fecha y hora, luego confirma la programación."}</span><button type="button" className="btn-primary small" onClick={scheduleTechnicalVisit}><Clock size={15}/> Programar fecha y hora</button></div>}
          <div className="installation-report-card">
            <div className="section-title"><ClipboardList size={18}/><div><h4>Cierre de la evaluación técnica</h4><p>La Orden de Pedido final para instalación se habilita cuando la evaluación está realizada y aprobada por el cliente.</p></div></div>
            <div className="form-grid">
              <div><label className="field-label">Estado de evaluación</label><div className={`order-status-box ${form.evaluacionTecnicaEstado === "Realizada" ? "done" : ""}`}>{form.evaluacionTecnicaEstado || "Pendiente"}</div></div>
              <div><label className="field-label">Aprobación del cliente</label><div className={`order-status-box ${form.evaluacionAprobadaCliente === "Aprobada" ? "done" : ""}`}>{form.evaluacionAprobadaCliente || "Pendiente"}</div></div>
            </div>
            <label className="field-label">Resultado de la evaluación técnica</label><textarea className="input" rows={3} value={form.evaluacionTecnicaInforme || ""} onChange={e => set("evaluacionTecnicaInforme", e.target.value)} placeholder="Condiciones encontradas, equipo recomendado, materiales y observaciones" />
            {isTechnicalArea && form.evaluacionTecnicaEstado !== "Realizada" && <button type="button" className="btn-primary" onClick={confirmTechnicalEvaluation}><CheckCircle2 size={16}/> Marcar evaluación como realizada</button>}
            <div className="form-grid">
              <div><label className="field-label">Nombre de quien aprueba</label><input className="input" value={form.evaluacionAprobadaPor || ""} onChange={e => set("evaluacionAprobadaPor", e.target.value)} placeholder="Cliente o responsable" /></div>
              <div><label className="field-label">Fecha de aprobación</label><div className="order-status-box">{form.evaluacionAprobadaEn ? new Date(form.evaluacionAprobadaEn).toLocaleString("es-GT") : "Pendiente"}</div></div>
            </div>
            {form.evaluacionAprobadaCliente !== "Aprobada" && <button type="button" className="btn-primary" onClick={approveEvaluation}><ShieldCheck size={16}/> Registrar aprobación del cliente</button>}
            <div className={`warranty-result ${technicalEvaluationReady ? "ready" : "blocked"}`}>{technicalEvaluationReady ? <><CheckCircle2 size={18}/> LISTA · Ya puede generarse la Orden de Pedido final</> : <><Clock size={18}/> PENDIENTE · Falta realizar o aprobar la evaluación</>}</div>
          </div>
          <h4>Programación e instalación</h4>
          <div className="form-grid">{field("Fecha de instalación", "fechaInstalacion", "date")}{select("Horario", "horario", ["Mañana", "Tarde", "Por confirmar"])}{field("Dirección de instalación", "direccion")}{field("Departamento", "departamento")}{field("Teléfono", "telefono")}{field("DPI / CUI", "dpi")}{field("NIT", "nit")}</div>
          <h4>Datos técnicos · {form.tipoOrden || "Calentadores"}</h4>
          {(form.tipoOrden || "Calentadores") === "Calentadores" && <div className="form-grid">{select("Niveles de la casa", "niveles", ["1", "2", "3", "4", "Otro"])}{select("Material del techo", "materialTecho", ["Lámina", "Terraza", "Teja", "Otro"])}{select("Tipo de techo", "tipoTecho", ["", "Plano", "1 agua", "2 aguas", "Varias aguas"])}{select("Tubería de agua caliente", "tuberiaCaliente", ["Sí", "No"])}{select("Medida tubería caliente", "medidaTuberiaCaliente", ["CPVC 1/2 pulgada", "CPVC 3/4 pulgada", "Otra"])}{select("Tubería de agua fría", "tuberiaFria", ["Sí", "No"])}{select("Medida tubería fría", "medidaTuberiaFria", ["PVC 1/2 pulgada", "PVC 3/4 pulgada", "Otra"])}{select("Presión de agua", "presionAgua", ["Baja", "Media", "Alta", "Muy alta"])}{select("¿Tiene otro calentador?", "otroCalentador", ["No", "Sí"])}{field("Detalle del otro calentador", "detalleOtroCalentador")}{select("¿Tiene variación de presión?", "variacionPresion", ["No", "Sí"])}{field("Detalle de la variación", "detalleVariacionPresion")}{field("Instalaciones adicionales", "instalacionesAdicionales")}{field("Distancia adicional (metros)", "distanciaAdicional", "number")}{select("Bomba hidroneumática", "bomba", ["Sí", "No"])}{select("Depósito para agua", "deposito", ["Sí", "No"])}{field("Altura del depósito", "alturaDeposito")}{select("Conecta al depósito", "conectaDeposito", ["Sí", "No"])}{select("Gradas al último nivel", "gradas", ["Sí", "No"])}{select("¿Entra camión a la casa?", "entraCamion", ["Sí", "No"])}</div>}
          {form.tipoOrden === "Servicios" && <div className="form-grid">{select("Tipo de servicio", "tipoServicio", ["Mantenimiento", "Reparación", "Instalación", "Desinstalación", "Otro"])}{field("Equipo existente", "equipoExistente")}{field("Falla reportada", "fallaReportada")}{field("Servicio requerido", "servicioRequerido")}{field("Materiales o repuestos previstos", "materialesServicio")}{select("¿Entra camión?", "entraCamion", ["Sí", "No"])}</div>}
          {form.tipoOrden === "Revisión técnica" && <div className="form-grid">{field("Motivo de la revisión", "motivoRevision")}{field("Equipo o sistema a revisar", "equipoExistente")}{field("Diagnóstico preliminar", "diagnosticoPreliminar")}{field("Mediciones necesarias", "medicionesTecnicas")}{select("Acceso al techo", "accesoTecho", ["Sí", "No", "Por confirmar"])}{field("Riesgos o condiciones especiales", "riesgosDetectados")}</div>}
          {form.tipoOrden === "Iluminación" && <div className="form-grid">{field("Área a iluminar (m²)", "areaIluminar", "number")}{field("Altura de instalación", "alturaInstalacionLuz")}{field("Cantidad de luminarias", "cantidadLuminarias", "number")}{field("Potencia de luminaria (W)", "potenciaLuminaria", "number")}{field("Ubicación del panel solar", "ubicacionPanelSolar")}{field("Horas de iluminación requeridas", "horasIluminacion")}{select("Material del techo", "materialTecho", ["Lámina", "Terraza", "Teja", "Otro"])}{select("¿Entra camión?", "entraCamion", ["Sí", "No"])}</div>}
          <h4>{isTechnicalArea ? "Observaciones técnicas" : "Pago y observaciones"}</h4>
          {!isTechnicalArea && <><div className="form-grid">{select("Estado del pago", "estadoPago", ["Pendiente", "Abonado", "Cancelado"])}{select("Forma de pago", "formaPago", ["Transferencia", "Contado", "Tarjeta débito/crédito", "Visa cuotas", "Financiamiento", "Cheque"])}{field("Primer abono (Q)", "abono", "number")}{field("Saldo pendiente (Q)", "saldo", "number")}</div>{form.estadoPago === "Cancelado" && <div className="paid-order-banner"><CheckCircle2 size={18} /> CANCELADO · Cliente pagó el total</div>}<div className="form-grid">{field("Promoción aplicada", "promocion")}{field("Garantía ofrecida", "garantia")}</div></>}
          <h4>Estado de la orden</h4>
          <div className="form-grid order-status-grid">
            <div><label className="field-label">Pago del cliente</label><div className={`order-status-box ${form.estadoPago === "Cancelado" ? "done" : ""}`}>{form.estadoPago === "Cancelado" ? "Cancelado (pagado)" : form.estadoPago || "Pendiente"}</div></div>
            <div><label className="field-label">Estado de instalación</label><select className="input" disabled={!['Jefe', 'Jefe técnico', 'Programación'].includes(currentUser?.rol) && !canCompleteInstallation} value={form.estadoInstalacion || "Pendiente de programación"} onChange={e => set("estadoInstalacion", e.target.value)}><option>Pendiente de programación</option><option>Programada para instalación</option><option>Instalada</option><option>Cancelada</option></select></div>
            <div><label className="field-label">Estado de Bodega</label><select className="input" disabled={!['Jefe', 'Bodega'].includes(currentUser?.rol)} value={form.estadoBodega || "Pendiente"} onChange={e => set("estadoBodega", e.target.value)}><option>Pendiente</option><option>En preparación</option><option>Listo para despacho</option><option>Despachado</option></select></div>
          </div>
          {(canCompleteInstallation || form.informeInstalacion?.fechaHora) && <div className="installation-report-card">
            <div className="section-title"><ClipboardList size={18}/><div><h4>Informe de instalación</h4><p>El cierre registra automáticamente la fecha, hora y ubicación del dispositivo.</p></div></div>
            <div className="form-grid">
              <div><label className="field-label">Persona que recibió el equipo</label><input className="input" disabled={!canCompleteInstallation} value={form.informeInstalacion?.recibidoPor || ""} onChange={e => setReport("recibidoPor", e.target.value)} /></div>
              <div><label className="field-label">Lugar registrado</label><div className="order-status-box">{form.informeInstalacion?.lugar || form.direccion || "Se confirmará al cerrar"}</div></div>
              <div><label className="field-label">Fecha y hora automática</label><div className="order-status-box">{form.informeInstalacion?.fechaHora ? new Date(form.informeInstalacion.fechaHora).toLocaleString("es-GT") : "Se registrará al cerrar"}</div></div>
              <div><label className="field-label">Coordenadas</label><div className="order-status-box">{form.informeInstalacion?.coordenadas || "Pendientes"}</div></div>
            </div>
            <label className="field-label">Informe del trabajo realizado</label><textarea className="input" rows={4} disabled={!canCompleteInstallation} value={form.informeInstalacion?.detalle || ""} onChange={e => setReport("detalle", e.target.value)} placeholder="Trabajo realizado, pruebas, funcionamiento, materiales utilizados y observaciones" />
            <label className="field-label">Evidencias del informe (enlaces compartidos)</label><textarea className="input" rows={2} disabled={!canCompleteInstallation} value={form.informeInstalacion?.evidencias || ""} onChange={e => setReport("evidencias", e.target.value)} placeholder="Pega un enlace por línea" />
            {canCompleteInstallation && <button type="button" className="btn-primary" onClick={registerInstallation}><MapPin size={16}/> Registrar instalación realizada</button>}
          </div>}
          {cotizacion.descuentoAutorizado && <div className="authorized-discount-order"><ShieldCheck size={18} /><div><strong>Descuento autorizado por {cotizacion.descuentoAutorizado.autorizadoPor}</strong><span>Total original: {fmtMoney(cotizacion.totalOriginal)} · Descuento: {fmtMoney(cotizacion.descuentoAutorizado.monto)} · Total autorizado: {fmtMoney(cotizacion.total)}</span></div></div>}
          <h4>Solicitud de garantía</h4>
          <div className="warranty-card">
            <div className="form-grid">
              {select("¿Se solicita garantía?", "garantiaSolicitada", ["No", "Sí"])}
              <div><label className="field-label">Cliente</label><div className="order-status-box">{contacto?.nombre || cotizacion.contactoNombre || "Sin registrar"}</div></div>
              <div><label className="field-label">Teléfono</label><div className="order-status-box">{contacto?.telefono || cotizacion.cliente?.telefono || "Sin registrar"}</div></div>
              <div><label className="field-label">Equipo</label><div className="order-status-box">{(cotizacion.items || []).filter(item => item.productoId !== "transporte_ruta").map(nombreItem).join(", ") || "Sin registrar"}</div></div>
            </div>
            {form.garantiaSolicitada === "Sí" && <>
              <label className="field-label">Razón por la que se solicita la garantía</label><textarea className="input" rows={3} value={form.garantiaMotivo || ""} onChange={e => set("garantiaMotivo", e.target.value)} placeholder="Describe por qué el cliente solicita la garantía" />
              <label className="field-label">Detalle de la falla y evidencias disponibles</label><textarea className="input" rows={3} value={form.garantiaDetalleFalla || ""} onChange={e => set("garantiaDetalleFalla", e.target.value)} placeholder="Falla reportada, fecha, pruebas realizadas y enlaces de evidencia" />
              <div className="warranty-approvals">
                <div><strong>Jefe técnico</strong><span className={`warranty-state ${form.garantiaJefeTecnico === "Aceptada" ? "approved" : form.garantiaJefeTecnico === "No aceptada" ? "denied" : ""}`}>{form.garantiaJefeTecnico}</span><small>{form.garantiaJefeTecnicoPor || "Pendiente de revisión"}</small>{currentUser?.rol === "Jefe técnico" && <div><button type="button" className="btn-primary small" onClick={() => warrantyDecision("tecnico", true)}>Aceptar</button><button type="button" className="btn-ghost small" onClick={() => warrantyDecision("tecnico", false)}>No aceptar</button></div>}</div>
                <div><strong>Ligia o Leyla</strong><span className={`warranty-state ${form.garantiaJefatura === "Aceptada" ? "approved" : form.garantiaJefatura === "No aceptada" ? "denied" : ""}`}>{form.garantiaJefatura}</span><small>{form.garantiaJefaturaPor || (form.garantiaJefeTecnico === "Aceptada" ? "Pendiente de revisión" : "Requiere primero al Jefe técnico")}</small>{isWarrantyBoss && <div><button type="button" className="btn-primary small" disabled={form.garantiaJefeTecnico !== "Aceptada"} onClick={() => warrantyDecision("jefatura", true)}>Aceptar</button><button type="button" className="btn-ghost small" onClick={() => warrantyDecision("jefatura", false)}>No aceptar</button></div>}</div>
              </div>
              <div className={`warranty-result ${warrantyReady ? "ready" : "blocked"}`}>{warrantyReady ? <><CheckCircle2 size={18} /> AUTORIZADA · Proceder con la garantía</> : <><Clock size={18} /> NO PROCEDER · Faltan autorizaciones</>}</div>
            </>}
          </div>
          <label className="field-label">Observaciones adicionales</label><textarea className="input" rows={3} value={form.observaciones} onChange={e => set("observaciones", e.target.value)} />
          <label className="field-label">Evidencias fotográficas (enlaces de Google Drive)</label>
          <textarea className="input" rows={3} value={form.evidenciasFotograficas || ""} onChange={e => set("evidenciasFotograficas", e.target.value)} placeholder="Pega un enlace compartido por línea" />
          {String(form.evidenciasFotograficas || "").split(/\n+/).filter(link => /^https?:\/\//i.test(link.trim())).length > 0 && <div className="photo-links">{String(form.evidenciasFotograficas).split(/\n+/).filter(link => /^https?:\/\//i.test(link.trim())).map((link, index) => <a key={`${link}-${index}`} href={link.trim()} target="_blank" rel="noreferrer"><Camera size={14} /> Abrir evidencia {index + 1}</a>)}</div>}
        </div>
        <div className="modal-foot"><button className="btn-ghost" onClick={onClose}>Cerrar</button>{onSave && <button className="btn-primary" onClick={saveOrder}><CheckCircle2 size={16} /> Guardar registro</button>}{onGenerate && !isTechnician && <button className="btn-primary" disabled={!technicalEvaluationReady} onClick={generateOrder}><Download size={16} /> Generar OP final</button>}{onAdvance && <button className="btn-primary" disabled={roleRequiresApprovedEvaluation(currentUser?.rol) && !technicalEvaluationReady} onClick={() => onAdvance(form)}><Send size={16} /> {advanceLabel}</button>}</div>
      </div>
    </div>
  );
}

function DiscountAuthorizationModal({ cotizacion, currentUser, mode = "request", onClose, onUpdate }) {
  const pending = cotizacion.descuentoSolicitud?.estado === "Pendiente" ? cotizacion.descuentoSolicitud : null;
  const canAuthorize = mode === "authorize" && Boolean(DISCOUNT_AUTHORIZERS[String(currentUser.email || "").toLowerCase()]);
  const [type, setType] = useState(pending?.tipo || "Porcentaje");
  const [value, setValue] = useState(String(pending?.valor || ""));
  const [reason, setReason] = useState(pending?.motivo || "");
  const baseTotal = Number(cotizacion.totalOriginal ?? cotizacion.total ?? 0);
  const numericValue = Number(value || 0);
  const discountAmount = type === "Porcentaje" ? baseTotal * numericValue / 100 : numericValue;
  const finalTotal = Math.max(0, baseTotal - discountAmount);
  const valid = numericValue > 0 && Boolean(reason.trim()) && discountAmount > 0 && discountAmount < baseTotal && (type !== "Porcentaje" || numericValue <= 100);

  const requestDiscount = async () => {
    if (!valid) return window.alert("Revisa el descuento. Debe ser mayor a cero, menor al total e incluir un motivo.");
    const request = { id: uid(), estado: "Pendiente", tipo: type, valor: numericValue, monto: discountAmount, motivo: reason.trim(), solicitadoPor: currentUser.nombre, solicitadoPorEmail: currentUser.email, solicitadoEn: new Date().toISOString() };
    try {
      await onUpdate({ ...cotizacion, totalOriginal: baseTotal, descuentoSolicitud: request, descuentoHistorial: [...(cotizacion.descuentoHistorial || []), { ...request, accion: "Solicitado" }] });
      window.alert("Solicitud enviada correctamente. Ya aparece en Descuentos pendientes para Ligia Molina y Leyla.");
      onClose();
    } catch (error) {
      console.error("No se pudo enviar la solicitud de descuento:", error);
      window.alert("No se pudo enviar la solicitud. Revisa tu conexión e inténtalo nuevamente.");
    }
  };

  const authorize = async () => {
    if (!canAuthorize) return window.alert("Solo Ligia Molina o Leyla pueden autorizar descuentos adicionales.");
    if (!valid) return window.alert("Revisa el descuento. Debe ser mayor a cero, menor al total e incluir un motivo.");
    const authorized = { id: pending?.id || uid(), estado: "Autorizado", tipo: type, valor: numericValue, monto: discountAmount, motivo: reason.trim(), solicitadoPor: pending?.solicitadoPor || currentUser.nombre, solicitadoPorEmail: pending?.solicitadoPorEmail || currentUser.email, solicitadoEn: pending?.solicitadoEn || new Date().toISOString(), autorizadoPor: currentUser.nombre, autorizadoPorEmail: currentUser.email, autorizadoEn: new Date().toISOString(), totalAnterior: baseTotal, totalFinal: finalTotal };
    try {
      await onUpdate({ ...cotizacion, totalOriginal: baseTotal, total: finalTotal, descuentoSolicitud: authorized, descuentoAutorizado: authorized, descuentoHistorial: [...(cotizacion.descuentoHistorial || []), { ...authorized, accion: "Autorizado" }] });
      window.alert(`Descuento autorizado por ${currentUser.nombre}. Nuevo total: ${fmtMoney(finalTotal)}.`); onClose();
    } catch (error) {
      console.error("No se pudo autorizar el descuento:", error);
      window.alert("No se pudo guardar la autorización. Revisa tu conexión e inténtalo nuevamente.");
    }
  };

  const reject = async () => {
    if (!canAuthorize || !pending) return;
    const rejected = { ...pending, estado: "Rechazado", rechazadoPor: currentUser.nombre, rechazadoPorEmail: currentUser.email, rechazadoEn: new Date().toISOString() };
    try {
      await onUpdate({ ...cotizacion, descuentoSolicitud: rejected, descuentoHistorial: [...(cotizacion.descuentoHistorial || []), { ...rejected, accion: "Rechazado" }] });
      onClose();
    } catch (error) {
      console.error("No se pudo rechazar el descuento:", error);
      window.alert("No se pudo guardar el rechazo. Revisa tu conexión e inténtalo nuevamente.");
    }
  };

  return <div className="modal-overlay" onClick={onClose}><div className="modal discount-modal" onClick={e => e.stopPropagation()}>
    <div className="modal-head"><div><h3>{canAuthorize ? "Autorizar descuento adicional" : "Solicitar descuento adicional"}</h3><small>Cotización {cotizacion.numero} · Total actual {fmtMoney(baseTotal)}</small></div><button className="icon-btn" onClick={onClose}><X size={18} /></button></div>
    <div className="modal-body">
      {pending && <div className="pending-discount"><Clock size={16}/><span>Solicitud pendiente de <strong>{pending.solicitadoPor}</strong></span></div>}
      <label className="field-label">Tipo de descuento</label><select className="input" value={type} disabled={canAuthorize} onChange={e => setType(e.target.value)}><option>Porcentaje</option><option>Monto fijo en quetzales</option></select>
      <label className="field-label">{type === "Porcentaje" ? "Porcentaje a descontar" : "Monto a descontar (Q)"}</label><input className="input" type="number" min="0" max={type === "Porcentaje" ? "100" : baseTotal} value={value} disabled={canAuthorize} onChange={e => setValue(e.target.value)} placeholder={type === "Porcentaje" ? "Ej. 5" : "Ej. 500"}/>
      <label className="field-label">Motivo del descuento</label><textarea className="input" rows={3} value={reason} disabled={canAuthorize} onChange={e => setReason(e.target.value)} placeholder="Ej. Cliente recurrente, compra de varias unidades o autorización comercial especial"/>
      <div className="discount-summary"><div><span>Descuento</span><strong>{type === "Porcentaje" ? `${numericValue || 0}% · ` : ""}{fmtMoney(discountAmount)}</strong></div><div><span>Nuevo total</span><strong>{fmtMoney(finalTotal)}</strong></div></div>
      <div className="audit-note"><ShieldCheck size={16}/><span>Se registrará quién solicita, quién autoriza, fecha, tipo, monto y motivo.</span></div>
    </div>
    <div className="modal-foot">{canAuthorize && pending && <button className="btn-ghost" onClick={reject}>Rechazar</button>}<button className="btn-ghost" onClick={onClose}>Cancelar</button><button className="btn-primary" disabled={!valid || (canAuthorize && !pending)} onClick={canAuthorize ? authorize : requestDiscount}>{canAuthorize ? <><ShieldCheck size={16}/> Autorizar descuento</> : <><Send size={16}/> Enviar solicitud</>}</button></div>
  </div></div>;
}

function CotizacionActions({ cotizacion, contacto, currentUser, vendedores, onUpdate, ordenSugerida }) {
  const [showOrder, setShowOrder] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [showDiscount, setShowDiscount] = useState(false);
  const discountState = cotizacion.descuentoSolicitud?.estado || "";
  const logAction = (canal, destinatario) => {
    const registro = {
      id: uid(), canal, destinatario,
      fechaHora: new Date().toISOString(),
      usuario: currentUser.nombre,
    };
    onUpdate({ ...cotizacion, estado: canal === "Orden de pedido" ? cotizacion.estado : "Enviada", envios: [...(cotizacion.envios || []), registro] });
  };

  const sendWhatsApp = () => {
    const phone = String(contacto?.telefono || "").replace(/\D/g, "");
    if (!phone) { window.alert("Este contacto no tiene número de teléfono registrado."); return; }
    const message = `Hola ${contacto.nombre}, le compartimos la cotización ${cotizacion.numero} de Casa Solar por ${fmtMoney(cotizacion.total)}. Tiene una vigencia de 30 días. Por favor adjunte el PDF descargado antes de enviar este mensaje.`;
    logAction("WhatsApp", contacto.telefono);
    window.open(`https://wa.me/502${phone.replace(/^502/, "")}?text=${encodeURIComponent(message)}`, "_blank", "noopener,noreferrer");
  };

  const sendEmail = () => {
    if (!contacto?.email) { window.alert("Este contacto no tiene correo electrónico registrado."); return; }
    const subject = `Cotización ${cotizacion.numero} - Casa Solar`;
    const body = `Estimado(a) ${contacto.nombre}:\n\nAdjuntamos la cotización ${cotizacion.numero} por ${fmtMoney(cotizacion.total)}, con vigencia de 30 días.\n\nImportante: adjunte el PDF descargado antes de enviar este correo.\n\nAtentamente,\n${cotizacion.vendedor}\nCasa Solar`;
    try { downloadQuotePdf(cotizacion, contacto, LOGO_FULL); } catch (error) { console.error("No se pudo descargar el PDF:", error); }
    const gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(contacto.email)}&su=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    const opened = window.open(gmailUrl, "_blank", "noopener,noreferrer");
    if (!opened) window.location.href = `mailto:${contacto.email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    logAction("Correo electrónico preparado", contacto.email);
    window.alert("Se descargó el PDF y se abrió el correo. Adjunta el archivo descargado antes de enviarlo.");
  };

  return (
    <div className="quote-actions">
      <button className="btn-ghost small" onClick={() => setShowEdit(true)} title="Cambiar o agregar productos"><Edit3 size={14} /> Editar</button>
      <button className="btn-ghost small" onClick={() => downloadQuotePdf(cotizacion, contacto, LOGO_FULL)} title="Descargar cotización PDF"><Download size={14} /> PDF</button>
      <button className="btn-ghost small" onClick={sendWhatsApp} title="Abrir WhatsApp y registrar el envío"><Send size={14} /> WhatsApp</button>
      <button className="btn-ghost small" onClick={sendEmail} title="Abrir correo y registrar el envío"><Mail size={14} /> Correo</button>
      <button className="btn-ghost small" onClick={() => setShowOrder(true)} title="Llenar y generar orden de pedido"><ShoppingCart size={14} /> Orden</button>
      {discountState !== "Pendiente" && discountState !== "Autorizado" && <button className="btn-ghost small discount-btn" onClick={() => setShowDiscount(true)} title="Enviar una solicitud a la bandeja de descuentos pendientes"><BadgePercent size={14} /> Solicitar descuento</button>}
      {discountState === "Pendiente" && <button className="btn-ghost small discount-btn" disabled title="Esperando autorización en la bandeja de Leyla o Ligia"><Clock size={14} /> Solicitud pendiente</button>}
      {cotizacion.descuentoSolicitud?.estado && <span className={`discount-status ${cotizacion.descuentoSolicitud.estado.toLowerCase()}`}>{cotizacion.descuentoSolicitud.estado}{cotizacion.descuentoSolicitud.autorizadoPor ? ` · ${cotizacion.descuentoSolicitud.autorizadoPor}` : ""}</span>}
      {(cotizacion.envios || []).length > 0 && (
        <span className="send-count" title={(cotizacion.envios || []).map(e => `${new Date(e.fechaHora).toLocaleString("es-GT")} · ${e.canal} · ${e.usuario}`).join("\n")}>
          {(cotizacion.envios || []).length} registro{cotizacion.envios.length === 1 ? "" : "s"}
        </span>
      )}
      {showOrder && <OrderFormModal cotizacion={{ ...cotizacion, ordenNumero: cotizacion.ordenNumero || ordenSugerida }} contacto={contacto} currentUser={currentUser} vendedores={vendedores} onClose={() => setShowOrder(false)} onSave={(form) => {
          const quoteForOrder = { ...cotizacion, ordenNumero: cotizacion.ordenNumero || ordenSugerida };
          const assigned = Boolean(form.tecnicoAsignadoEmail);
          const presencial = String(form.tipoEvaluacion).includes("presencial");
          const nextStage = presencial ? (assigned ? "Técnico" : "Jefe técnico") : "Programación";
          const action = presencial ? (assigned ? `Visita presencial asignada a ${form.tecnicoAsignadoNombre}` : "Visita presencial enviada al Jefe técnico") : `${form.tipoEvaluacion} enviada a Programación`;
          const history = [...(quoteForOrder.ordenFlujo?.historial || []), { accion: action, usuario: currentUser.nombre, email: currentUser.email || "", fecha: new Date().toISOString() }];
          if (form.fechaInstalacion) history.push({ accion: `Instalación programada para ${form.fechaInstalacion}; notificada a Programación, Bodega y Facturación`, usuario: currentUser.nombre, email: currentUser.email || "", fecha: new Date().toISOString() });
          onUpdate({ ...quoteForOrder, ordenPedido: form, ordenFlujo: { ...(quoteForOrder.ordenFlujo || {}), etapa: nextStage, programacionNotificada: Boolean(form.fechaInstalacion), bodegaNotificada: Boolean(form.fechaInstalacion), facturacionNotificada: Boolean(form.fechaInstalacion), historial: history } });
          setShowOrder(false);
        }} onGenerate={(form) => {
        try {
          const quoteForOrder = { ...cotizacion, ordenNumero: cotizacion.ordenNumero || ordenSugerida };
          downloadOrderPdf(quoteForOrder, contacto, LOGO_FULL, form);
          const registro = { id: uid(), canal: "Orden de pedido", destinatario: "Descarga interna", fechaHora: new Date().toISOString(), usuario: currentUser.nombre };
          onUpdate({ ...quoteForOrder, ordenPedido: form, envios: [...(quoteForOrder.envios || []), registro] });
          setShowOrder(false);
        } catch (error) {
          console.error("No se pudo generar la orden:", error);
          window.alert(`No se pudo generar la orden PDF. ${error?.message || "Inténtalo nuevamente."}`);
        }
      }} />}
      {showEdit && <CotizacionModal contactos={[contacto].filter(Boolean)} initialContactId={cotizacion.contactoId} vendedor={cotizacion.vendedor} initial={cotizacion} onClose={() => setShowEdit(false)} onSave={(updated) => {
        if (cotizacion.descuentoAutorizado) {
          const invalidatedAt = new Date().toISOString();
          const invalidatedBy = currentUser?.displayName || currentUser?.email || "Usuario";
          onUpdate({
            ...updated,
            totalOriginal: updated.total,
            descuentoAutorizado: null,
            descuentoSolicitud: null,
            descuentoHistorial: [
              ...(cotizacion.descuentoHistorial || []),
              { accion: "Invalidado por edición de la cotización", fecha: invalidatedAt, usuario: invalidatedBy, email: currentUser?.email || "" },
            ],
          });
          alert("La cotización cambió. El descuento anterior quedó guardado en el historial y deberá autorizarse nuevamente.");
        } else {
          onUpdate(updated);
        }
        setShowEdit(false);
      }} />}
      {showDiscount && <DiscountAuthorizationModal mode="request" cotizacion={cotizacion} currentUser={currentUser} onClose={() => setShowDiscount(false)} onUpdate={onUpdate} />}
    </div>
  );
}

function ContactosView({ contactos, vendedores, currentUser, onAdd, onImport, onAssign, onOpen }) {
  const [search, setSearch] = useState("");
  const [filterEstado, setFilterEstado] = useState("todos");
  const [filterVendedor, setFilterVendedor] = useState(currentUser.rol === "Jefe" ? "todos" : currentUser.nombre);
  const [showModal, setShowModal] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [selected, setSelected] = useState([]);
  const [assignTo, setAssignTo] = useState(vendedores[0]?.nombre || "");

  const visibles = useMemo(() => {
    return contactos.filter(c => {
      if (currentUser.rol !== "Jefe" && c.vendedor !== currentUser.nombre) return false;
      if (filterVendedor !== "todos" && c.vendedor !== filterVendedor) return false;
      if (filterEstado !== "todos" && c.estado !== filterEstado) return false;
      if (search && !c.nombre.toLowerCase().includes(search.toLowerCase()) && !c.telefono.includes(search)) return false;
      return true;
    }).sort((a, b) => (b.fecha || "").localeCompare(a.fecha || ""));
  }, [contactos, filterEstado, filterVendedor, search, currentUser]);

  return (
    <div>
      <div className="page-head row">
        <div>
          <h2>Contactos</h2>
          <p>Llamadas entrantes y contactos por redes sociales.</p>
        </div>
        <div className="row">
          <button className="btn-ghost" onClick={() => setShowImport(true)}><Upload size={16} /> Importar Excel</button>
          <button className="btn-primary" onClick={() => setShowModal(true)}><Plus size={16} /> Nuevo contacto</button>
        </div>
      </div>

      <div className="filters">
        <div className="search-box">
          <Search size={15} />
          <input placeholder="Buscar por nombre o teléfono…" value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        <select className="input filter-select" value={filterEstado} onChange={e => setFilterEstado(e.target.value)}>
          <option value="todos">Todos los estados</option>
          {ESTADOS_CONTACTO.map(e => <option key={e} value={e}>{e}</option>)}
        </select>
        {currentUser.rol === "Jefe" && (
          <select className="input filter-select" value={filterVendedor} onChange={e => setFilterVendedor(e.target.value)}>
            <option value="todos">Todos los vendedores</option>
            {vendedores.map(v => <option key={v.id} value={v.nombre}>{v.nombre}</option>)}
          </select>
        )}
      </div>

      {currentUser.rol === "Jefe" && (
        <div className="bulk-bar">
          <label><input type="checkbox" checked={visibles.length > 0 && visibles.every(c => selected.includes(c.id))} onChange={e => setSelected(e.target.checked ? visibles.map(c => c.id) : [])} /> Seleccionar los {visibles.length} visibles</label>
          <span>{selected.length} seleccionados</span>
          <select className="input compact" value={assignTo} onChange={e => setAssignTo(e.target.value)}>
            {vendedores.map(v => <option key={v.id} value={v.nombre}>{v.nombre}</option>)}
          </select>
          <button className="btn-primary small" disabled={!selected.length || !assignTo} onClick={() => { onAssign(selected, assignTo); setSelected([]); }}><Users2 size={14} /> Asignar vendedor</button>
        </div>
      )}

      {visibles.length === 0 ? (
        <div className="empty-state">No hay contactos que coincidan. Crea uno nuevo para empezar.</div>
      ) : (
        <div className="card-list">
          {visibles.map(c => {
            const Icon = canalIcon(c.canal);
            return (
              <div key={c.id} className="contact-row" onClick={() => onOpen(c.id)}>
                {currentUser.rol === "Jefe" && <input type="checkbox" checked={selected.includes(c.id)} onClick={e => e.stopPropagation()} onChange={e => setSelected(ids => e.target.checked ? [...new Set([...ids, c.id])] : ids.filter(id => id !== c.id))} aria-label={`Seleccionar a ${c.nombre}`} />}
                <div className="channel-icon"><Icon size={16} /></div>
                <div className="contact-main">
                  <div className="contact-name">{c.nombre}</div>
                  <div className="contact-sub">{productoNombre(c.productoInteres)} · {c.vendedor}</div>
                </div>
                <div className="contact-date muted">{fmtDate(c.fecha)}</div>
                <Badge estado={c.estado} />
                <ChevronRight size={16} className="muted" />
              </div>
            );
          })}
        </div>
      )}

      {showModal && (
        <ContactModal vendedores={vendedores} currentUser={currentUser} onClose={() => setShowModal(false)}
          onSave={(form) => { onAdd(form); setShowModal(false); }} />
      )}
      {showImport && <ExcelImportModal contactos={currentUser.rol === "Jefe" ? contactos : contactos.filter(c => c.vendedor === currentUser.nombre)} currentUser={currentUser} onClose={() => setShowImport(false)} onImport={(rows, mode) => { onImport(rows, mode); setShowImport(false); }} />}
    </div>
  );
}

function ContactDetail({ contacto, cotizaciones, seguimientos, vendedores, currentUser, onBack, onUpdateContacto, onAddCotizacion, onUpdateCotizacion, onAddSeguimiento }) {
  const [modal, setModal] = useState(null);
  const misCot = cotizaciones.filter(c => c.contactoId === contacto.id);
  const orderYear = new Date().getFullYear();
  const maxOrder = cotizaciones.filter(c => String(c.ordenNumero || "").startsWith(`OP-${orderYear}-`)).reduce((max, c) => Math.max(max, Number(String(c.ordenNumero).split("-").pop()) || 0), 0);
  const ordenSugerida = `OP-${orderYear}-${String(maxOrder + 1).padStart(4, "0")}`;
  const misSeg = seguimientos.filter(s => s.contactoId === contacto.id).sort((a, b) => b.fecha.localeCompare(a.fecha));
  const Icon = canalIcon(contacto.canal);

  return (
    <div>
      <button className="btn-ghost small" onClick={onBack}><ArrowLeft size={14} /> Volver a contactos</button>

      <div className="detail-head">
        <div className="channel-icon lg"><Icon size={20} /></div>
        <div style={{ flex: 1 }}>
          <h2>{contacto.nombre}</h2>
          <p className="muted">{contacto.telefono || "Sin teléfono"} {contacto.email ? "· " + contacto.email : ""}</p>
        </div>
        <button className="btn-ghost" onClick={() => setModal("editar-contacto")}><Edit3 size={15} /> Editar contacto</button>
        <select className="input" style={{ width: 170 }} value={contacto.estado}
          onChange={e => onUpdateContacto({ ...contacto, estado: e.target.value })}>
          {ESTADOS_CONTACTO.map(e => <option key={e} value={e}>{e}</option>)}
        </select>
      </div>

      <div className="detail-meta">
        <span><strong>Canal:</strong> {contacto.canal}</span>
        <span><strong>Interés:</strong> {productoNombre(contacto.productoInteres)}</span>
        <span><strong>Vendedor:</strong> {contacto.vendedor}</span>
        <span><strong>Registrado:</strong> {fmtDate(contacto.fecha)}</span>
        <span><strong>Promociones:</strong> {contacto.permisoPromociones || "Pendiente de confirmar"}</span>
      </div>
      {contacto.notas && <div className="section-card"><h3>Notas</h3><p>{contacto.notas}</p></div>}

      <div className="section-card">
        <div className="row" style={{ justifyContent: "space-between" }}>
          <h3>Cotizaciones ({misCot.length})</h3>
          <button className="btn-ghost small" onClick={() => setModal("cotizacion")}><Plus size={14} /> Nueva</button>
        </div>
        {misCot.length === 0 ? <p className="muted">Sin cotizaciones todavía.</p> : (
          <table className="table">
            <thead><tr><th>Número</th><th>Fecha</th><th>Productos</th><th>Total</th><th>Estado</th><th>Documentos y envío</th></tr></thead>
            <tbody>
              {misCot.map(c => (
                <tr key={c.id}>
                  <td><strong>{c.numero || "—"}</strong></td>
                  <td>{fmtDate(c.fecha)}</td>
                  <td>{c.items.map(nombreItem).join(", ")}</td>
                  <td>{fmtMoney(c.total)}</td>
                  <td><Badge estado={c.estado} /></td>
                  <td><CotizacionActions cotizacion={c} contacto={contacto} currentUser={currentUser} vendedores={vendedores} onUpdate={onUpdateCotizacion} ordenSugerida={ordenSugerida} /></td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div className="section-card">
        <div className="row" style={{ justifyContent: "space-between" }}>
          <h3>Seguimientos ({misSeg.length})</h3>
          <button className="btn-ghost small" onClick={() => setModal("seguimiento")}><Plus size={14} /> Nuevo</button>
        </div>
        {misSeg.length === 0 ? <p className="muted">Sin seguimientos todavía.</p> : (
          <div className="mini-list">
            {misSeg.map(s => (
              <div key={s.id} className="mini-row">
                <span className="muted">{fmtDate(s.fecha)}</span>
                <span>{s.tipo}</span>
                <span style={{ flex: 1 }}>{s.notas}</span>
                {s.proximoSeguimiento && <span className="muted">Próx: {fmtDate(s.proximoSeguimiento)}</span>}
              </div>
            ))}
          </div>
        )}
      </div>

      {modal === "cotizacion" && (
        <CotizacionModal contactos={[contacto]} initialContactId={contacto.id} vendedor={contacto.vendedor}
          onClose={() => setModal(null)} onSave={(data) => { onAddCotizacion(data); setModal(null); }} />
      )}
      {modal === "editar-contacto" && (
        <ContactModal initial={contacto} vendedores={vendedores} currentUser={currentUser}
          onClose={() => setModal(null)} onSave={(updated) => { onUpdateContacto(updated); setModal(null); }} />
      )}
      {modal === "seguimiento" && (
        <SeguimientoModal contactos={[contacto]} initialContactId={contacto.id} vendedor={contacto.vendedor}
          onClose={() => setModal(null)} onSave={async (data) => { await onAddSeguimiento(data); setModal(null); }} />
      )}
    </div>
  );
}

function CotizacionesView({ cotizaciones, contactos, vendedores, currentUser, onAdd, onUpdateEstado, onUpdateCotizacion }) {
  const [showModal, setShowModal] = useState(false);
  const [filterEstado, setFilterEstado] = useState("todos");
  const visibles = cotizaciones.filter(c => {
    if (currentUser.rol !== "Jefe" && c.vendedor !== currentUser.nombre) return false;
    if (filterEstado !== "todos" && c.estado !== filterEstado) return false;
    return true;
  }).sort((a, b) => b.fecha.localeCompare(a.fecha));
  const orderYear = new Date().getFullYear();
  const maxOrder = cotizaciones.filter(c => String(c.ordenNumero || "").startsWith(`OP-${orderYear}-`)).reduce((max, c) => Math.max(max, Number(String(c.ordenNumero).split("-").pop()) || 0), 0);
  const ordenSugerida = `OP-${orderYear}-${String(maxOrder + 1).padStart(4, "0")}`;

  return (
    <div>
      <div className="page-head row">
        <div><h2>Cotizaciones</h2><p>Propuestas enviadas a clientes potenciales.</p></div>
        <button className="btn-primary" onClick={() => setShowModal(true)} disabled={contactos.length === 0}>
          <Plus size={16} /> Nueva cotización
        </button>
      </div>
      <div className="filters">
        <select className="input filter-select" value={filterEstado} onChange={e => setFilterEstado(e.target.value)}>
          <option value="todos">Todos los estados</option>
          {ESTADOS_COTIZACION.map(e => <option key={e} value={e}>{e}</option>)}
        </select>
      </div>
      {visibles.length === 0 ? (
        <div className="empty-state">Todavía no hay cotizaciones registradas.</div>
      ) : (
        <table className="table">
          <thead><tr><th>Número</th><th>Fecha</th><th>Cliente</th><th>Productos</th><th>Total</th><th>Vendedor</th><th>Estado</th><th>Acciones</th></tr></thead>
          <tbody>
            {visibles.map(c => {
              const contacto = contactos.find(k => k.id === c.contactoId) || c.cliente;
              return (
                <tr key={c.id}>
                  <td><strong>{c.numero || "—"}</strong></td>
                  <td>{fmtDate(c.fecha)}</td>
                  <td>{contacto ? contacto.nombre : "—"}</td>
                  <td>{c.items.map(nombreItem).join(", ")}</td>
                  <td>{fmtMoney(c.total)}</td>
                  <td>{c.vendedor}</td>
                  <td>
                    <select className="input compact" value={c.estado} onChange={e => onUpdateEstado(c.id, e.target.value)}>
                      {ESTADOS_COTIZACION.map(e => <option key={e} value={e}>{e}</option>)}
                    </select>
                  </td>
                  <td><CotizacionActions cotizacion={c} contacto={contacto} currentUser={currentUser} vendedores={vendedores} onUpdate={onUpdateCotizacion} ordenSugerida={ordenSugerida} /></td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
      {showModal && (
        <CotizacionModal contactos={contactos} vendedor={currentUser.nombre}
          onClose={() => setShowModal(false)} onSave={(data) => { onAdd(data); setShowModal(false); }} />
      )}
    </div>
  );
}

function SeguimientoHiloModal({ contacto, seguimientos, onClose, onAdd }) {
  const historial = [...seguimientos].sort((a, b) => seguimientoOrden(a).localeCompare(seguimientoOrden(b)));
  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal follow-thread-modal" onClick={e => e.stopPropagation()}>
        <div className="modal-head">
          <div><h3>Hilo de seguimiento</h3><small>{contacto?.nombre || historial[0]?.contactoNombre} · {historial.length} registro{historial.length === 1 ? "" : "s"}</small></div>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>
        <div className="modal-body follow-thread">
          {historial.map((s, index) => (
            <div className="follow-message" key={s.id}>
              <div className="follow-dot"><ClipboardList size={14} /></div>
              <div className="follow-bubble">
                <div className="follow-meta"><strong>{s.tipo}</strong><span>{fmtDate(s.fecha)} · {s.vendedor}</span></div>
                <p>{s.notas}</p>
                {s.proximoSeguimiento && <small><Clock size={12} /> Próximo seguimiento: {fmtDate(s.proximoSeguimiento)}</small>}
              </div>
              {index < historial.length - 1 && <span className="follow-line" />}
            </div>
          ))}
        </div>
        <div className="modal-foot">
          <button className="btn-ghost" onClick={onClose}>Cerrar</button>
          <button className="btn-primary" onClick={onAdd}><Plus size={16} /> Agregar al hilo</button>
        </div>
      </div>
    </div>
  );
}

function SeguimientosView({ seguimientos, contactos, currentUser, onAdd }) {
  const [newContactId, setNewContactId] = useState("");
  const [threadContactId, setThreadContactId] = useState("");
  const visibles = seguimientos.filter(s => currentUser.rol === "Jefe" || s.vendedor === currentUser.nombre)
    .sort((a, b) => seguimientoOrden(b).localeCompare(seguimientoOrden(a)));
  const hilos = Object.values(visibles.reduce((acc, s) => {
    const key = s.contactoId;
    if (!acc[key]) acc[key] = { contactoId: key, contactoNombre: s.contactoNombre, registros: [] };
    acc[key].registros.push(s);
    return acc;
  }, {})).sort((a, b) => seguimientoOrden(b.registros[0]).localeCompare(seguimientoOrden(a.registros[0])));
  const threadContact = contactos.find(c => c.id === threadContactId);
  const threadRecords = visibles.filter(s => s.contactoId === threadContactId);

  return (
    <div>
      <div className="page-head row">
        <div><h2>Seguimientos</h2><p>Historial de contacto con cada cliente.</p></div>
        <button className="btn-primary" onClick={() => setNewContactId("__nuevo__")} disabled={contactos.length === 0}>
          <Plus size={16} /> Nuevo seguimiento
        </button>
      </div>
      {visibles.length === 0 ? (
        <div className="empty-state">Todavía no hay seguimientos registrados.</div>
      ) : (
        <div className="card-list">
          {hilos.map(hilo => {
            const ultimo = hilo.registros[0];
            const proximo = hilo.registros.find(s => s.proximoSeguimiento)?.proximoSeguimiento;
            return <div key={hilo.contactoId} className="seg-row follow-client-row">
              <div className="channel-icon"><ClipboardList size={16} /></div>
              <div className="contact-main">
                <div className="contact-name">{hilo.contactoNombre}</div>
                <div className="contact-sub">{hilo.registros.length} seguimiento{hilo.registros.length === 1 ? "" : "s"} · Último: {ultimo.tipo}</div>
                <div className="contact-sub follow-preview">{ultimo.notas}</div>
                {proximo && <div className="contact-sub follow-next">Próximo: {fmtDate(proximo)}</div>}
              </div>
              <div className="contact-date muted">{fmtDate(ultimo.fecha)}</div>
              <button className="btn-ghost small follow-open" onClick={() => setThreadContactId(hilo.contactoId)}>Ver hilo</button>
            </div>;
          })}
        </div>
      )}
      {threadContactId && (
        <SeguimientoHiloModal contacto={threadContact} seguimientos={threadRecords}
          onClose={() => setThreadContactId("")} onAdd={() => { setNewContactId(threadContactId); setThreadContactId(""); }} />
      )}
      {newContactId && (
        <SeguimientoModal contactos={contactos} initialContactId={newContactId === "__nuevo__" ? "" : newContactId} vendedor={currentUser.nombre}
          onClose={() => setNewContactId("")} onSave={async (data) => { await onAdd(data); setNewContactId(""); }} />
      )}
    </div>
  );
}

function CatalogoView() {
  const grupos = CATALOGO.reduce((acc, p) => { (acc[p.categoria] = acc[p.categoria] || []).push(p); return acc; }, {});
  return (
    <div>
      <div className="page-head"><h2>Catálogo</h2><p>Línea de productos y servicios de Casa Solar.</p></div>
      {Object.entries(grupos).map(([cat, items]) => (
        <div key={cat} className="section-card">
          <h3>{cat}s</h3>
          <div className="catalog-grid">
            {items.map(p => (
              <div key={p.id} className="catalog-item"><Wrench size={15} /> {p.nombre}</div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

function EquipoView({ vendedores, currentUser, onAdd, onCreateAccess, onRemove, onUpdate, onResetPassword, onToggleAccess }) {
  const [nombre, setNombre] = useState("");
  const [telefono, setTelefono] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [rol, setRol] = useState("Vendedor");
  const [departamentosCobertura, setDepartamentosCobertura] = useState("");
  const [creating, setCreating] = useState(false);
  const [message, setMessage] = useState("");
  const leylaCanCreate = String(currentUser.email || "").toLowerCase() === "leyla.flores@gmail.com";

  const createAccess = async () => {
    if (!nombre.trim() || !email.trim() || password.length < 6) {
      setMessage("Completa nombre y correo. La contraseña debe tener al menos 6 caracteres.");
      return;
    }
    setCreating(true);
    setMessage("");
    try {
      await onCreateAccess({ nombre: nombre.trim(), email: email.trim(), password, rol, telefono: telefono.trim(), departamentosCobertura: departamentosCobertura.trim() });
      setMessage(`Acceso creado correctamente para ${nombre.trim()}.`);
      setNombre(""); setTelefono(""); setEmail(""); setPassword(""); setRol("Vendedor"); setDepartamentosCobertura("");
    } catch (error) {
      const code = String(error?.code || "");
      if (code.includes("email-already-in-use")) setMessage("Ese correo ya tiene un usuario registrado.");
      else if (code.includes("invalid-email")) setMessage("El correo electrónico no es válido.");
      else if (code.includes("weak-password")) setMessage("La contraseña es demasiado sencilla; utiliza al menos 6 caracteres.");
      else setMessage("No fue posible crear el acceso. Revisa los datos e inténtalo nuevamente.");
    } finally {
      setCreating(false);
    }
  };
  return (
    <div>
      <div className="page-head"><h2>Equipo y usuarios</h2><p>Administra vendedores y accesos al CRM.</p></div>
      {leylaCanCreate && <div className="section-card user-access-card">
        <div className="section-title"><ShieldCheck size={18} /><div><h3>Crear acceso al CRM</h3><p>Solo Leyla puede crear usuarios con correo y contraseña.</p></div></div>
        <div className="user-access-grid">
          <label><span className="field-label">Nombre completo</span><input className="input" value={nombre} onChange={e => setNombre(e.target.value)} placeholder="Nombre del usuario" /></label>
          <label><span className="field-label">Correo electrónico</span><input className="input" type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="usuario@correo.com" /></label>
          <label><span className="field-label">Contraseña inicial</span><span className="password-field"><input className="input" type={showPassword ? "text" : "password"} value={password} onChange={e => setPassword(e.target.value)} placeholder="Mínimo 6 caracteres" /><button type="button" className="icon-btn" onClick={() => setShowPassword(value => !value)} aria-label={showPassword ? "Ocultar contraseña" : "Mostrar contraseña"}>{showPassword ? <EyeOff size={16}/> : <Eye size={16}/>}</button></span></label>
          <label><span className="field-label">Tipo de usuario</span><select className="input" value={rol} onChange={e => setRol(e.target.value)}><option>Vendedor</option><option>Jefe técnico</option><option>Técnico</option><option>Programación</option><option>Bodega</option><option>Facturación</option><option>Jefe</option></select></label>
          <label><span className="field-label">WhatsApp</span><input className="input" value={telefono} onChange={e => setTelefono(e.target.value)} placeholder="Número opcional" /></label>
          {rol === "Técnico" && <label><span className="field-label">Departamentos que cubre</span><input className="input" value={departamentosCobertura} onChange={e => setDepartamentosCobertura(e.target.value)} placeholder="Ej. Guatemala, Sacatepéquez y Chimaltenango" /></label>}
        </div>
        {message && <p className={message.includes("correctamente") ? "form-success" : "login-error"}>{message}</p>}
        <button className="btn-primary" onClick={createAccess} disabled={creating}><Plus size={16} /> {creating ? "Creando acceso…" : "Crear usuario"}</button>
        <p className="privacy-note">Por seguridad, Firebase no permite ver una contraseña después de crearla. Si alguien la olvida, utiliza “Restablecer contraseña”; recibirá un enlace seguro en su correo.</p>
      </div>}
      <div className="section-card">
        <h3>Vendedores disponibles</h3>
        <div className="item-row">
          <input className="input" placeholder="Nombre del vendedor" value={nombre} onChange={e => setNombre(e.target.value)} />
          <input className="input" placeholder="WhatsApp del vendedor" value={telefono} onChange={e => setTelefono(e.target.value)} />
          <button className="btn-primary" onClick={() => { if (nombre.trim()) { onAdd(nombre.trim(), telefono.trim()); setNombre(""); setTelefono(""); } }}>
            <Plus size={16} /> Agregar
          </button>
        </div>
        <div className="mini-list" style={{ marginTop: 16 }}>
          {vendedores.map(v => (
            <div key={v.id} className="mini-row">
              <input className="input compact" style={{ minWidth: 190, flex: 1 }} defaultValue={v.nombre} aria-label={`Nombre de ${v.nombre}`} onBlur={e => onUpdate({ ...v, nombre: e.target.value.trim() })} />
              <input className="input compact" style={{ flex: 1 }} defaultValue={v.telefono || ""} placeholder="Número de WhatsApp" onBlur={e => onUpdate({ ...v, telefono: e.target.value.trim() })} />
              <span className={`badge ${v.activo === false ? "badge-gray" : "badge-green"}`}>{v.activo === false ? "Suspendido" : "Activo"}</span>
              {v.email && <button className="btn-ghost small" onClick={() => onResetPassword(v)} title="Enviar enlace de cambio al correo"><KeyRound size={14}/> Restablecer</button>}
              <button className="btn-ghost small" onClick={() => onToggleAccess(v, v.activo === false)}>{v.activo === false ? <><UserCheck size={14}/> Reactivar</> : <><UserX size={14}/> Suspender</>}</button>
              <button className="icon-btn" onClick={() => onRemove(v)} title="Eliminar colaborador del CRM"><Trash2 size={14} /></button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function TechnicalOrdersView({ cotizaciones, contactos, vendedores, currentUser, onUpdate }) {
  const [selected, setSelected] = useState(null);
  const role = currentUser.rol;
  const visible = cotizaciones.filter(quote => {
    if (!quote.ordenPedido) return false;
    const stage = quote.ordenFlujo?.etapa || "Pendiente de asignación";
    if (["Jefe", "Jefe técnico"].includes(role)) return true;
    if (role === "Técnico") return String(quote.ordenPedido.tecnicoAsignadoEmail || "").toLowerCase() === String(currentUser.email || "").toLowerCase();
    if (role === "Programación") return ["Programación", "Bodega y Facturación", "Completada"].includes(stage);
    if (["Bodega", "Facturación"].includes(role)) return ["Bodega y Facturación", "Completada"].includes(stage);
    return false;
  });
  const selectedQuote = selected ? cotizaciones.find(item => item.id === selected) : null;
  const selectedContact = selectedQuote ? contactos.find(item => item.id === selectedQuote.contactoId) : null;
  const advanceConfig = quote => {
    const stage = quote.ordenFlujo?.etapa;
    if (role === "Técnico" && stage === "Técnico") return { label: "Enviar evaluación aprobada", stage: "Programación", action: "Evaluación realizada y aprobada por el cliente; lista para Orden de Pedido final" };
    if (role === "Programación" && stage === "Programación") return { label: "Enviar a Bodega y Facturación", stage: "Bodega y Facturación", action: "Programación enviada a Bodega y Facturación" };
    if (role === "Bodega" && stage === "Bodega y Facturación" && !quote.ordenFlujo?.bodegaCompletado) return { label: "Marcar revisión de Bodega", stage, action: "Revisión de Bodega completada", flag: "bodegaCompletado" };
    if (role === "Facturación" && stage === "Bodega y Facturación" && !quote.ordenFlujo?.facturacionCompletada) return { label: "Marcar Facturación", stage, action: "Facturación completada", flag: "facturacionCompletada" };
    return null;
  };
  const saveRecord = (quote, form) => {
    const presencial = String(form.tipoEvaluacion).includes("presencial");
    let stage = quote.ordenFlujo?.etapa || (presencial ? "Jefe técnico" : "Programación");
    if (role === "Jefe técnico") stage = presencial ? (form.tecnicoAsignadoEmail ? "Técnico" : "Jefe técnico") : "Programación";
    if (form.informeInstalacion?.fechaHora) stage = "Completada";
    const detail = role === "Jefe técnico" && presencial
      ? (form.tecnicoAsignadoEmail ? `Jefe técnico asignó visita a ${form.tecnicoAsignadoNombre}` : "Jefe técnico dejó la visita sin técnico asignado")
      : "Registro actualizado";
    const history = [...(quote.ordenFlujo?.historial || []), { accion: detail, usuario: currentUser.nombre, email: currentUser.email || "", rol: role, fecha: new Date().toISOString() }];
    if (form.fechaInstalacion && form.fechaInstalacion !== quote.ordenPedido?.fechaInstalacion) history.push({ accion: `Fecha de instalación establecida o cambiada a ${form.fechaInstalacion}; Programación, Bodega y Facturación actualizadas`, usuario: currentUser.nombre, email: currentUser.email || "", rol: role, fecha: new Date().toISOString() });
    if (form.informeInstalacion?.fechaHora && form.informeInstalacion.fechaHora !== quote.ordenPedido?.informeInstalacion?.fechaHora) history.push({ accion: `Instalación finalizada; recibió ${form.informeInstalacion.recibidoPor}`, usuario: currentUser.nombre, email: currentUser.email || "", rol: role, fecha: form.informeInstalacion.fechaHora });
    onUpdate({ ...quote, ordenPedido: form, ordenFlujo: { ...(quote.ordenFlujo || {}), etapa: stage, programacionNotificada: Boolean(form.fechaInstalacion), bodegaNotificada: Boolean(form.fechaInstalacion), facturacionNotificada: Boolean(form.fechaInstalacion), historial: history } });
    setSelected(null);
  };
  const advance = (quote, form, config) => {
    const nextFlow = { ...(quote.ordenFlujo || {}), etapa: config.stage, [config.flag || "ultimaAccion"]: config.flag ? true : config.action };
    if (config.stage === "Bodega y Facturación" && nextFlow.bodegaCompletado && nextFlow.facturacionCompletada) nextFlow.etapa = "Completada";
    nextFlow.historial = [...(quote.ordenFlujo?.historial || []), { accion: config.action, usuario: currentUser.nombre, email: currentUser.email || "", rol: role, fecha: new Date().toISOString() }];
    onUpdate({ ...quote, ordenPedido: form, ordenFlujo: nextFlow });
    setSelected(null);
  };
  return <div>
    <div className="page-head"><h2>Órdenes de pedido y asignación técnica</h2><p>Abre cada orden para modificarla, guardarla, descargarla en PDF y asignar, cambiar o retirar al técnico instalador.</p></div>
    <div className="section-card">
      {visible.length === 0 ? <div className="empty-state">No tienes órdenes asignadas en esta etapa.</div> : <div className="mini-list">{visible.map(quote => {
        const contact = contactos.find(item => item.id === quote.contactoId);
        return <button className="technical-order-row" key={quote.id} onClick={() => setSelected(quote.id)}>
          <div><strong>{quote.ordenNumero || quote.numero.replace("CS-", "OP-")}</strong><span>{contact?.nombre || quote.contactoNombre} · {quote.ordenPedido.tipoEvaluacion || "Evaluación por definir"} · {quote.ordenPedido.departamentoVisita || contact?.departamento || "Sin departamento"}</span></div>
          <div><span className="badge badge-blue">{quote.ordenFlujo?.etapa || "Pendiente"}</span><small>Evaluación: {quote.ordenPedido.evaluacionTecnicaEstado || "Pendiente"} · Cliente: {quote.ordenPedido.evaluacionAprobadaCliente || "Pendiente"} · {quote.ordenPedido.ordenFinalGenerada ? "OP final generada" : "OP final pendiente"}</small><small>{quote.ordenPedido.tecnicoAsignadoNombre || "Sin técnico"} · {quote.ordenPedido.estadoPago === "Cancelado" ? "Pago cancelado" : quote.ordenPedido.estadoInstalacion || "Sin programar"} · {quote.ordenPedido.estadoBodega || "Bodega pendiente"}</small></div>
        </button>;
      })}</div>}
    </div>
    {selectedQuote && <OrderFormModal cotizacion={selectedQuote} contacto={selectedContact} currentUser={currentUser} vendedores={vendedores} onClose={() => setSelected(null)} onSave={form => saveRecord(selectedQuote, form)} onGenerate={form => { downloadOrderPdf(selectedQuote, selectedContact || selectedQuote.cliente || {}, LOGO_FULL, form); saveRecord(selectedQuote, form); }} {...(advanceConfig(selectedQuote) ? { onAdvance: form => advance(selectedQuote, form, advanceConfig(selectedQuote)), advanceLabel: advanceConfig(selectedQuote).label } : {})} />}
  </div>;
}

function InstallationReportsView({ cotizaciones, contactos, currentUser }) {
  const reports = cotizaciones.filter(quote => quote.ordenPedido?.informeInstalacion?.fechaHora).filter(quote => {
    if (["Jefe", "Jefe técnico", "Programación"].includes(currentUser.rol)) return true;
    return String(quote.ordenPedido.tecnicoAsignadoEmail || "").toLowerCase() === String(currentUser.email || "").toLowerCase();
  }).sort((a, b) => String(b.ordenPedido.informeInstalacion.fechaHora).localeCompare(String(a.ordenPedido.informeInstalacion.fechaHora)));
  return <div>
    <div className="page-head"><h2>Informes de instalación</h2><p>Registro final de instalaciones realizadas, recepción del equipo, ubicación y responsable técnico.</p></div>
    <div className="section-card">
      {reports.length === 0 ? <div className="empty-state">Todavía no hay informes de instalación finalizados.</div> : <table className="table"><thead><tr><th>Fecha y hora</th><th>Orden</th><th>Cliente</th><th>Técnico</th><th>Recibió</th><th>Lugar</th><th>Informe</th></tr></thead><tbody>{reports.map(quote => {
        const contact = contactos.find(item => item.id === quote.contactoId) || quote.cliente || {};
        const report = quote.ordenPedido.informeInstalacion;
        return <tr key={quote.id}><td>{new Date(report.fechaHora).toLocaleString("es-GT")}</td><td>{quote.ordenNumero || quote.numero.replace("CS-", "OP-")}</td><td>{contact.nombre || quote.contactoNombre}</td><td>{report.tecnicoNombre || quote.ordenPedido.tecnicoAsignadoNombre}</td><td>{report.recibidoPor}</td><td>{report.lugar}<small className="table-note">{report.coordenadas || "Sin GPS"}</small></td><td><button className="btn-ghost small" onClick={() => downloadInstallationReportPdf(quote, contact, LOGO_FULL, quote.ordenPedido)}><Download size={14}/> PDF</button></td></tr>;
      })}</tbody></table>}
    </div>
  </div>;
}

function DiscountRequestsView({ cotizaciones, contactos, solicitudes, currentUser, onUpdate }) {
  const [processingId, setProcessingId] = useState("");
  const pendingMap = new Map();
  solicitudes.filter(request => request.estado === "Pendiente").forEach(request => pendingMap.set(request.id, request));
  cotizaciones.forEach(quote => {
    const request = quote.descuentoSolicitud;
    if (request?.estado === "Pendiente") pendingMap.set(request.id, {
      ...request,
      ...(pendingMap.get(request.id) || {}),
      cotizacionId: quote.id,
      numero: quote.numero,
      contactoId: quote.contactoId,
      contactoNombre: quote.contactoNombre,
      vendedor: quote.vendedor,
      totalBase: quote.totalOriginal ?? quote.total,
    });
  });
  const pending = [...pendingMap.values()].sort((a, b) => String(b.solicitadoEn || "").localeCompare(String(a.solicitadoEn || "")));
  const currentEmail = String(currentUser.email || "").toLowerCase();
  const canLigia = currentEmail === "ligiaeugeniamolina@gmail.com";
  const canLeyla = currentEmail === "leyla.flores@gmail.com";
  const resolve = async (request, decision) => {
    const quote = cotizaciones.find(item => item.id === request.cotizacionId)
      || cotizaciones.find(item => item.descuentoSolicitud?.id === request.id);
    if (!quote) return window.alert("No se encontró la cotización original. Actualiza la página e inténtalo nuevamente.");
    if (decision === "Ligia" && !canLigia) return window.alert("Esta autorización debe realizarla Ligia desde su propio usuario.");
    if (decision === "Leyla" && !canLeyla) return window.alert("Esta autorización debe realizarla Leyla desde su propio usuario.");
    if (decision === "No autorizado" && !canLigia && !canLeyla) return window.alert("Solo Ligia o Leyla pueden rechazar esta solicitud.");
    setProcessingId(request.id);
    const now = new Date().toISOString();
    const baseTotal = Number(request.totalBase ?? quote.totalOriginal ?? quote.total ?? 0);
    const discountAmount = Number(request.monto || 0);
    const authorized = decision !== "No autorizado";
    const resolvedRequest = authorized ? {
      ...request,
      estado: "Autorizado",
      autorizadoPor: decision === "Ligia" ? "Ligia Eugenia Molina" : "Leyla Flores",
      autorizadoPorEmail: currentEmail,
      autorizadoEn: now,
      totalAnterior: baseTotal,
      totalFinal: Math.max(0, baseTotal - discountAmount),
    } : {
      ...request,
      estado: "No autorizado",
      rechazadoPor: currentUser.nombre,
      rechazadoPorEmail: currentEmail,
      rechazadoEn: now,
    };
    try {
      await onUpdate({
        ...quote,
        totalOriginal: baseTotal,
        total: authorized ? resolvedRequest.totalFinal : quote.total,
        descuentoSolicitud: resolvedRequest,
        descuentoAutorizado: authorized ? resolvedRequest : null,
        descuentoHistorial: [...(quote.descuentoHistorial || []), { ...resolvedRequest, accion: authorized ? `Autorizado por ${decision}` : "No autorizado" }],
      });
      window.alert(authorized
        ? `Descuento autorizado por ${resolvedRequest.autorizadoPor}. La cotización ${quote.numero} ahora tiene un total de ${fmtMoney(resolvedRequest.totalFinal)}.`
        : `La solicitud de descuento de la cotización ${quote.numero} fue marcada como no autorizada.`);
    } catch (error) {
      console.error("No se pudo resolver la solicitud de descuento:", error);
      window.alert("No se pudo guardar la decisión. Revisa la conexión e inténtalo nuevamente.");
    } finally {
      setProcessingId("");
    }
  };
  return <div><div className="page-head"><h2>Descuentos pendientes</h2><p>Solicitudes enviadas por los vendedores para autorización.</p></div>
    <div className="section-card">{pending.length === 0 ? <div className="empty-state">No hay descuentos pendientes de revisión.</div> : <table className="table discount-requests-table"><thead><tr><th>Fecha</th><th>Vendedor</th><th>Cliente</th><th>Cotización</th><th>Descuento</th><th>Motivo</th><th>Decisión</th></tr></thead><tbody>{pending.map(request => <tr key={request.id}><td>{new Date(request.solicitadoEn).toLocaleDateString("es-GT")}</td><td>{request.solicitadoPor}</td><td>{contactos.find(c => c.id === request.contactoId)?.nombre || request.contactoNombre}</td><td>{request.numero}</td><td>{request.tipo === "Porcentaje" ? `${request.valor}% (${fmtMoney(request.monto)})` : fmtMoney(request.monto)}</td><td>{request.motivo}</td><td><div className="discount-decision-buttons"><button className="btn-primary small" disabled={!canLigia || processingId === request.id} onClick={() => resolve(request, "Ligia")}><ShieldCheck size={13}/> Autorizado por Ligia</button><button className="btn-primary small" disabled={!canLeyla || processingId === request.id} onClick={() => resolve(request, "Leyla")}><ShieldCheck size={13}/> Autorizado por Leyla</button><button className="btn-ghost small reject-discount" disabled={processingId === request.id} onClick={() => resolve(request, "No autorizado")}><X size={13}/> No autorizado</button></div></td></tr>)}</tbody></table>}</div>
  </div>;
}

function OperationsView({ mode, cotizaciones, contactos, currentUser, onUpdate }) {
  const allOrders = cotizaciones.filter(quote => quote.ordenPedido);
  const orders = mode === "programacion"
    ? allOrders.filter(quote => Boolean(quote.ordenPedido.fechaInstalacion) || ["Programación", "Bodega y Facturación", "Completada"].includes(quote.ordenFlujo?.etapa))
    : mode === "bodega"
      ? allOrders.filter(quote => Boolean(quote.ordenPedido.fechaInstalacion))
      : allOrders.filter(quote => Boolean(quote.ordenPedido.fechaInstalacion));
  const updateOrder = (quote, fields, action) => {
    const history = [...(quote.ordenFlujo?.historial || []), { accion: action, usuario: currentUser.nombre, email: currentUser.email || "", fecha: new Date().toISOString() }];
    const hasDate = Boolean(fields.fechaInstalacion ?? quote.ordenPedido.fechaInstalacion);
    onUpdate({ ...quote, ordenPedido: { ...quote.ordenPedido, ...fields }, ordenFlujo: { ...(quote.ordenFlujo || {}), programacionNotificada: hasDate, bodegaNotificada: hasDate, facturacionNotificada: hasDate, historial: history } });
  };
  const contactName = quote => contactos.find(c => c.id === quote.contactoId)?.nombre || quote.contactoNombre || "Sin cliente";
  if (mode === "programacion") {
    const scheduled = orders.filter(q => q.ordenPedido.fechaInstalacion).sort((a,b) => a.ordenPedido.fechaInstalacion.localeCompare(b.ordenPedido.fechaInstalacion));
    const pending = orders.filter(q => !q.ordenPedido.fechaInstalacion);
    const rows = list => list.map(q => <tr key={q.id}><td>{q.ordenNumero || q.numero.replace("CS-","OP-")}</td><td>{contactName(q)}</td><td>{q.ordenPedido.tipoEvaluacion || q.ordenPedido.tipoOrden}</td><td><input className="input compact" type="date" value={q.ordenPedido.fechaInstalacion || ""} onChange={e => updateOrder(q,{fechaInstalacion:e.target.value, estadoInstalacion:e.target.value ? "Programada para instalación" : "Pendiente de programación"},"Fecha programada actualizada")} /></td><td><select className="input compact" value={q.ordenPedido.horario || "Por confirmar"} onChange={e => updateOrder(q,{horario:e.target.value},"Horario actualizado")}><option>Mañana</option><option>Tarde</option><option>Por confirmar</option></select></td><td>{q.ordenPedido.tecnicoAsignadoNombre || "Sin técnico"}</td></tr>);
    return <div><div className="page-head"><h2>Programación</h2><p>Órdenes organizadas por fecha programada.</p></div><div className="section-card"><h3>Pendientes sin fecha ({pending.length})</h3>{pending.length ? <table className="table"><thead><tr><th>Orden</th><th>Cliente</th><th>Tipo</th><th>Fecha</th><th>Horario</th><th>Técnico</th></tr></thead><tbody>{rows(pending)}</tbody></table> : <div className="empty-state">No hay órdenes pendientes.</div>}</div><div className="section-card"><h3>Órdenes programadas</h3><table className="table"><thead><tr><th>Orden</th><th>Cliente</th><th>Tipo</th><th>Fecha</th><th>Horario</th><th>Técnico</th></tr></thead><tbody>{rows(scheduled)}</tbody></table></div></div>;
  }
  if (mode === "bodega") return <div><div className="page-head"><h2>Bodega</h2><p>Equipos que deben prepararse y despacharse.</p></div><div className="section-card"><table className="table"><thead><tr><th>Fecha</th><th>Orden</th><th>Vendedor</th><th>Equipos</th><th>Estado de despacho</th></tr></thead><tbody>{orders.sort((a,b)=>(a.ordenPedido.fechaInstalacion||"9999").localeCompare(b.ordenPedido.fechaInstalacion||"9999")).map(q => <tr key={q.id}><td>{q.ordenPedido.fechaInstalacion ? fmtDate(q.ordenPedido.fechaInstalacion) : "Pendiente"}</td><td>{q.ordenNumero || q.numero.replace("CS-","OP-")}</td><td>{q.vendedor}</td><td>{q.items.filter(i=>i.productoId!=="transporte_ruta").map(i=>`${i.cantidad} × ${nombreItem(i)}`).join(", ")}</td><td><select className="input compact" value={q.ordenPedido.estadoBodega || "Pendiente"} onChange={e=>updateOrder(q,{estadoBodega:e.target.value},`Bodega: ${e.target.value}`)}><option>Pendiente</option><option>En preparación</option><option>Listo para despacho</option><option>Despachado</option></select></td></tr>)}</tbody></table></div></div>;
  return <div><div className="page-head"><h2>Facturación</h2><p>Facturas que deben generarse para los clientes.</p></div><div className="section-card"><table className="table"><thead><tr><th>Orden</th><th>Cliente</th><th>NIT</th><th>Total</th><th>Pago</th><th>Factura</th><th>Número</th></tr></thead><tbody>{orders.map(q => { const c=contactos.find(x=>x.id===q.contactoId)||q.cliente||{}; return <tr key={q.id}><td>{q.ordenNumero||q.numero.replace("CS-","OP-")}</td><td>{c.nombre||q.contactoNombre}</td><td>{c.nit||q.ordenPedido.nit||"C/F"}</td><td>{fmtMoney(q.total)}</td><td>{q.ordenPedido.estadoPago||"Pendiente"}</td><td><select className="input compact" value={q.ordenPedido.estadoFactura||"Pendiente"} onChange={e=>updateOrder(q,{estadoFactura:e.target.value},`Facturación: ${e.target.value}`)}><option>Pendiente</option><option>En proceso</option><option>Generada</option><option>Enviada al cliente</option></select></td><td><input className="input compact" value={q.ordenPedido.numeroFactura||""} onChange={e=>updateOrder(q,{numeroFactura:e.target.value},"Número de factura actualizado")} placeholder="Serie / número" /></td></tr>;})}</tbody></table></div></div>;
}

function PlanningView({ cotizaciones, contactos }) {
  const [view, setView] = useState("Día"); const [date, setDate] = useState(todayISO());
  const orders = cotizaciones.filter(q=>q.ordenPedido?.fechaInstalacion).filter(q=>{ const d=q.ordenPedido.fechaInstalacion; if(view==="Día") return d===date; if(view==="Semana"){ const start=new Date(`${date}T12:00:00`); start.setDate(start.getDate()-start.getDay()+1); const end=new Date(start); end.setDate(end.getDate()+6); return d>=start.toISOString().slice(0,10)&&d<=end.toISOString().slice(0,10);} return d.slice(0,7)===date.slice(0,7); }).sort((a,b)=>(a.ordenPedido.horario||"").localeCompare(b.ordenPedido.horario||""));
  return <div><div className="page-head"><h2>Planificación</h2><p>Consulta la agenda por día, semana, mes y horario.</p></div><div className="section-card planning-filters"><div className="role-toggle">{["Día","Semana","Mes"].map(v=><button key={v} className={view===v?"active":""} onClick={()=>setView(v)}>{v}</button>)}</div><input className="input" type="date" value={date} onChange={e=>setDate(e.target.value)} /></div><div className="section-card">{orders.length===0?<div className="empty-state">No hay actividades para el periodo.</div>:<div className="timeline-list">{orders.map(q=><div className="timeline-item" key={q.id}><strong>{q.ordenPedido.horario||"Por confirmar"}</strong><div><h3>{contactos.find(c=>c.id===q.contactoId)?.nombre||q.contactoNombre}</h3><p>{fmtDate(q.ordenPedido.fechaInstalacion)} · {q.ordenPedido.tipoOrden} · {q.ordenPedido.tecnicoAsignadoNombre||"Sin técnico"}</p></div></div>)}</div>}</div></div>;
}

function SalesReportsView({ cotizaciones, vendedores, currentUser }) {
  const now = new Date();
  const [periodType, setPeriodType] = useState("Mes");
  const [month, setMonth] = useState(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`);
  const [year, setYear] = useState(String(now.getFullYear()));
  const [from, setFrom] = useState(`${now.getFullYear()}-01-01`);
  const [to, setTo] = useState(todayISO());
  const [seller, setSeller] = useState(currentUser.rol === "Jefe" ? "todos" : currentUser.nombre);
  const sellerUsers = vendedores.filter(user => ["Vendedor", "Jefe"].includes(user.rol || "Vendedor"));
  const inPeriod = dateValue => {
    const date = String(dateValue || "").slice(0, 10);
    if (periodType === "Mes") return date.startsWith(month);
    if (periodType === "Año") return date.startsWith(year);
    return (!from || date >= from) && (!to || date <= to);
  };
  const sold = cotizaciones.filter(quote => {
    if (quote.estado !== "Aceptada" && quote.ordenPedido?.estadoPago !== "Cancelado") return false;
    if (currentUser.rol !== "Jefe" && quote.vendedor !== currentUser.nombre) return false;
    if (seller !== "todos" && quote.vendedor !== seller) return false;
    return inPeriod(quote.ordenPedido?.fechaCancelado || quote.fechaVenta || quote.fecha);
  });
  const advances = cotizaciones.filter(quote => quote.ordenPedido?.fechaAnticipo && Number(quote.ordenPedido?.abono || 0) > 0 && inPeriod(quote.ordenPedido.fechaAnticipo) && (currentUser.rol === "Jefe" || quote.vendedor === currentUser.nombre) && (seller === "todos" || quote.vendedor === seller));
  const advanceAmount = advances.reduce((sum, quote) => sum + Number(quote.ordenPedido?.abono || 0), 0);
  const total = sold.reduce((sum, quote) => sum + Number(quote.total || 0), 0);
  const average = sold.length ? total / sold.length : 0;
  const sellerRows = [...new Set(sold.map(quote => quote.vendedor || "Sin vendedor"))].map(name => {
    const rows = sold.filter(quote => (quote.vendedor || "Sin vendedor") === name);
    return { name, count: rows.length, total: rows.reduce((sum, quote) => sum + Number(quote.total || 0), 0) };
  }).sort((a, b) => b.total - a.total);
  const groups = {};
  sold.forEach(quote => {
    const date = String(quote.ordenPedido?.fechaCancelado || quote.fechaVenta || quote.fecha || "").slice(0, 10);
    const key = periodType === "Año" ? date.slice(5, 7) : date.slice(8, 10);
    groups[key] = (groups[key] || 0) + Number(quote.total || 0);
  });
  const chartData = Object.entries(groups).sort(([a], [b]) => a.localeCompare(b)).map(([key, value]) => ({
    label: periodType === "Año" ? ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"][Number(key) - 1] : `Día ${Number(key)}`,
    value,
  }));
  const maxChart = Math.max(1, ...chartData.map(item => item.value));
  const productMap = {};
  sold.forEach(quote => (quote.items || []).filter(item => item.productoId !== "transporte_ruta").forEach(item => {
    const product = nombreItem(item); const category = item.categoria || categoriaProducto(item.productoId); const key = `${category}|${product}`;
    if (!productMap[key]) productMap[key] = { product, category, quantity: 0, total: 0 };
    productMap[key].quantity += Number(item.cantidad || 0); productMap[key].total += Number(item.cantidad || 0) * Number(item.precioUnitario || 0);
  }));
  const productRows = Object.values(productMap).sort((a,b) => b.total - a.total);
  return <div className="sales-report printable-report">
    <div className="page-head report-head"><div><h2>Reportes de ventas</h2><p>Incluye cotizaciones aceptadas y órdenes con pago “Cancelado”.</p></div><button className="btn-primary" onClick={() => window.print()}><Download size={16} /> Imprimir o guardar PDF</button></div>
    <div className="section-card report-filters">
      <label><span className="field-label">Periodo</span><select className="input" value={periodType} onChange={e => setPeriodType(e.target.value)}><option>Mes</option><option>Año</option><option>Rango de fechas</option></select></label>
      {periodType === "Mes" && <label><span className="field-label">Mes</span><input className="input" type="month" value={month} onChange={e => setMonth(e.target.value)} /></label>}
      {periodType === "Año" && <label><span className="field-label">Año</span><input className="input" type="number" min="2020" max="2100" value={year} onChange={e => setYear(e.target.value)} /></label>}
      {periodType === "Rango de fechas" && <><label><span className="field-label">Desde</span><input className="input" type="date" value={from} onChange={e => setFrom(e.target.value)} /></label><label><span className="field-label">Hasta</span><input className="input" type="date" value={to} onChange={e => setTo(e.target.value)} /></label></>}
      {currentUser.rol === "Jefe" && <label><span className="field-label">Vendedor</span><select className="input" value={seller} onChange={e => setSeller(e.target.value)}><option value="todos">Ventas generales</option>{sellerUsers.map(user => <option key={user.id || user.nombre} value={user.nombre}>{user.nombre}</option>)}</select></label>}
    </div>
    <div className="kpi-grid report-kpis"><div className="kpi-card"><div className="kpi-label">Ventas cerradas</div><div className="kpi-value">{sold.length}</div></div><div className="kpi-card"><div className="kpi-label">Monto vendido</div><div className="kpi-value">{fmtMoney(total)}</div></div><div className="kpi-card"><div className="kpi-label">Anticipos logrados</div><div className="kpi-value">{advances.length}</div><small>{fmtMoney(advanceAmount)} recibidos</small></div><div className="kpi-card"><div className="kpi-label">Venta promedio</div><div className="kpi-value">{fmtMoney(average)}</div></div><div className="kpi-card"><div className="kpi-label">Mejor vendedor</div><div className="kpi-value report-name">{sellerRows[0]?.name || "Sin ventas"}</div></div></div>
    <div className="section-card"><h3>Rendimiento del periodo</h3>{chartData.length === 0 ? <div className="empty-state">No hay ventas cerradas en el periodo seleccionado.</div> : <div className="sales-chart">{chartData.map(item => <div className="sales-bar-row" key={item.label}><span>{item.label}</span><div className="sales-bar-track"><div className="sales-bar" style={{ width: `${Math.max(3, item.value / maxChart * 100)}%` }} /></div><strong>{fmtMoney(item.value)}</strong></div>)}</div>}</div>
    {currentUser.rol === "Jefe" && <div className="section-card"><h3>Ventas por vendedor</h3><table className="table"><thead><tr><th>Vendedor</th><th>Ventas</th><th>Monto total</th><th>Participación</th></tr></thead><tbody>{sellerRows.map(row => <tr key={row.name}><td>{row.name}</td><td>{row.count}</td><td>{fmtMoney(row.total)}</td><td>{total ? `${(row.total / total * 100).toFixed(1)}%` : "0%"}</td></tr>)}</tbody></table></div>}
    <div className="section-card"><h3>Productos vendidos por producto y categoría</h3><table className="table"><thead><tr><th>Categoría</th><th>Producto</th><th>Unidades</th><th>Monto vendido</th></tr></thead><tbody>{productRows.map(row => <tr key={`${row.category}-${row.product}`}><td>{row.category}</td><td>{row.product}</td><td>{row.quantity}</td><td>{fmtMoney(row.total)}</td></tr>)}</tbody></table></div>
    <div className="section-card"><h3>Detalle de ventas</h3><table className="table"><thead><tr><th>Fecha</th><th>Cotización</th><th>Cliente</th><th>Vendedor</th><th>Estado</th><th>Total</th></tr></thead><tbody>{sold.map(quote => <tr key={quote.id}><td>{fmtDate(quote.ordenPedido?.fechaCancelado || quote.fechaVenta || quote.fecha)}</td><td>{quote.numero}</td><td>{quote.contactoNombre || quote.cliente?.nombre || "—"}</td><td>{quote.vendedor}</td><td>{quote.ordenPedido?.estadoPago === "Cancelado" ? "Cancelado" : "Aceptada"}</td><td>{fmtMoney(quote.total)}</td></tr>)}</tbody></table></div>
    <div className="section-card advances-section"><div className="section-title"><ShoppingCart size={18}/><div><h3>Anticipos recibidos</h3><p>Se muestran después de las ventas completas y cerradas.</p></div></div>{advances.length === 0 ? <div className="empty-state">No hay anticipos registrados en el periodo seleccionado.</div> : <><table className="table"><thead><tr><th>Fecha</th><th>Cliente</th><th>Vendedor</th><th>Orden / Cotización</th><th>Total de venta</th><th>Anticipo</th><th>Saldo</th></tr></thead><tbody>{advances.map(quote => <tr key={quote.id}><td>{fmtDate(quote.ordenPedido.fechaAnticipo)}</td><td>{quote.contactoNombre || quote.cliente?.nombre || "—"}</td><td>{quote.vendedor}</td><td>{quote.ordenNumero || quote.numero}</td><td>{fmtMoney(quote.total)}</td><td><strong>{fmtMoney(quote.ordenPedido.abono)}</strong></td><td>{fmtMoney(quote.ordenPedido.saldo || Math.max(0, Number(quote.total || 0) - Number(quote.ordenPedido.abono || 0)))}</td></tr>)}</tbody><tfoot><tr><th colSpan="5">Total de anticipos</th><th>{fmtMoney(advanceAmount)}</th><th></th></tr></tfoot></table></>}</div>
  </div>;
}

export default function CasaSolarCRM() {
  const [loading, setLoading] = useState(true);
  const [currentUser, setCurrentUser] = useState(null);
  const [vendedores, setVendedores] = useState([]);
  const [contactos, setContactos] = useState([]);
  const [cotizaciones, setCotizaciones] = useState([]);
  const [descuentoSolicitudes, setDescuentoSolicitudes] = useState([]);
  const [seguimientos, setSeguimientos] = useState([]);
  const [campaigns, setCampaigns] = useState([]);
  const [tab, setTab] = useState("dashboard");
  const [selectedId, setSelectedId] = useState(null);

  useEffect(() => {
    const unsubscribe = observeAuth(async (firebaseUser) => {
      if (!firebaseUser) {
        setCurrentUser(null);
        setLoading(false);
        return;
      }

      setLoading(true);
      const profile = await profileFromFirebaseUser(firebaseUser);
      if (profile.activo === false) {
        await logoutFirebase();
        window.alert("Este acceso está suspendido. Comunícate con Leyla para revisar tu estado en la empresa.");
        setLoading(false);
        return;
      }
      setCurrentUser(profile);
      if (["Jefe técnico", "Técnico"].includes(profile.rol)) setTab("ordenes-tecnicas");
      if (profile.rol === "Programación") setTab("programacion");
      if (profile.rol === "Bodega") setTab("bodega");
      if (profile.rol === "Facturación") setTab("facturacion");
      const [v, c, q, s, camp, discountQueue] = await Promise.all([
        storageGet("casasolar:vendedores", true),
        storageGet("casasolar:contactos", true),
        storageGet("casasolar:cotizaciones", true),
        storageGet("casasolar:seguimientos", true),
        storageGet("casasolar:campaigns", true),
        storageGet("casasolar:descuentos", true),
      ]);
      let sellerList = v || [];
      const linkedSeller = sellerList.find(item => item.uid === profile.uid || item.email === profile.email || item.nombre === profile.nombre);
      if (linkedSeller?.activo === false) {
        await setCRMUserActive(profile.uid, false, "Validación automática del CRM");
        await logoutFirebase();
        window.alert("Este acceso está suspendido. Comunícate con Leyla para revisar tu estado en la empresa.");
        setLoading(false);
        return;
      }
      if (linkedSeller) {
        const linkedProfile = { ...linkedSeller, uid: profile.uid, email: profile.email };
        sellerList = sellerList.map(item => item.id === linkedSeller.id ? linkedProfile : item);
        setCurrentUser({ ...profile, nombre: linkedProfile.nombre });
        await storageSet("casasolar:vendedores", sellerList, true);
      }
      const loadedQuotes = q || [];
      const counters = {};
      loadedQuotes.forEach(item => {
        const match = String(item.numero || "").match(/^CS-(\d{4})-(\d+)$/);
        if (match) counters[match[1]] = Math.max(counters[match[1]] || 0, Number(match[2]));
      });
      let repairedNumbers = false;
      const normalizedQuotes = loadedQuotes.map(item => {
        if (item.numero) return item;
        const year = String(item.fecha || todayISO()).slice(0, 4);
        counters[year] = (counters[year] || 0) + 1;
        repairedNumbers = true;
        return { ...item, numero: `CS-${year}-${String(counters[year]).padStart(4, "0")}` };
      });
      const normalizedDiscounts = Array.isArray(discountQueue) ? [...discountQueue] : [];
      const loadedFollowups = Array.isArray(s) ? [...s] : [];
      const installationFollowups = [];
      normalizedQuotes.forEach(quote => {
        const installationDate = quote.ordenPedido?.fechaInstalacion;
        if (!quote.contactoId || !installationDate) return;
        const eventKey = `instalacion-programada:${quote.id}:${installationDate}`;
        if (loadedFollowups.some(item => item.eventoClave === eventKey)) return;
        const contact = (c || []).find(item => item.id === quote.contactoId);
        installationFollowups.push({
          id: uid(), contactoId: quote.contactoId, contactoNombre: contact?.nombre || quote.contactoNombre || "Cliente",
          tipo: "Instalación programada", notas: `Instalación programada para ${installationDate}${quote.ordenPedido.horario ? ` · ${quote.ordenPedido.horario}` : ""}. Orden ${quote.ordenNumero || quote.numero}.`,
          proximoSeguimiento: installationDate, vendedor: quote.vendedor || contact?.vendedor || "Sistema",
          fecha: String(quote.ordenPedido.visitaTecnicaProgramadaEn || quote.fecha || todayISO()).slice(0, 10), fechaHora: quote.ordenPedido.visitaTecnicaProgramadaEn || new Date().toISOString(),
          creadoEn: new Date().toISOString(), creadoPorEmail: "", origen: "Sistema", cotizacionId: quote.id, eventoClave: eventKey,
        });
      });
      let repairedDiscounts = false;
      normalizedQuotes.forEach(quote => {
        const request = quote.descuentoSolicitud;
        if (request?.estado === "Pendiente" && !normalizedDiscounts.some(item => item.id === request.id)) {
          normalizedDiscounts.push({ ...request, cotizacionId: quote.id, numero: quote.numero, contactoId: quote.contactoId, contactoNombre: quote.contactoNombre, vendedor: quote.vendedor, totalBase: quote.totalOriginal ?? quote.total });
          repairedDiscounts = true;
        }
      });
      setVendedores(sellerList);
      setContactos(c || []);
      setCotizaciones(normalizedQuotes);
      setDescuentoSolicitudes(normalizedDiscounts);
      setSeguimientos([...installationFollowups, ...loadedFollowups]);
      if (installationFollowups.length) {
        try {
          await Promise.all(installationFollowups.map(record => appendSharedData("casasolar:seguimientos", record)));
        } catch (error) {
          console.error("No se pudo completar la conciliación de instalaciones y seguimientos:", error);
        }
      }
      const loadedCampaigns = camp?.length ? camp : [DEFAULT_CAMPAIGN];
      setCampaigns(loadedCampaigns);
      if (!camp?.length) {
        await storageSet("casasolar:campaigns", loadedCampaigns, true);
        await savePublicCampaign(DEFAULT_CAMPAIGN);
      }
      if (repairedNumbers) await storageSet("casasolar:cotizaciones", normalizedQuotes, true);
      if (repairedDiscounts) await storageSet("casasolar:descuentos", normalizedDiscounts, true);
      if (!linkedSeller) {
        const updated = [...sellerList, { id: uid(), nombre: profile.nombre, uid: profile.uid, email: profile.email }];
        setVendedores(updated);
        setCurrentUser(profile);
        await storageSet("casasolar:vendedores", updated, true);
      }
      setLoading(false);
    });
    return unsubscribe;
  }, []);

  useEffect(() => {
    if (!currentUser) return undefined;
    const unsubscribeProfile = subscribeCRMUserProfile(currentUser.uid, profile => {
      if (profile?.activo === false) {
        window.alert("Tu acceso al CRM fue suspendido. La sesión se cerrará ahora.");
        logoutFirebase();
      }
    }, error => console.error("No se pudo verificar el estado del acceso:", error));
    const unsubscribeSellers = subscribeSharedData("casasolar:vendedores", value => {
      if (Array.isArray(value)) setVendedores(value);
    }, error => console.error("No se pudo actualizar el equipo en tiempo real:", error));
    const unsubscribeContacts = subscribeSharedData("casasolar:contactos", value => {
      if (Array.isArray(value)) setContactos(value);
    }, error => console.error("No se pudieron actualizar los contactos en tiempo real:", error));
    const unsubscribeQuotes = subscribeSharedData("casasolar:cotizaciones", value => {
      if (Array.isArray(value)) setCotizaciones(value);
    }, error => console.error("No se pudieron actualizar las solicitudes en tiempo real:", error));
    const unsubscribeFollowups = subscribeSharedData("casasolar:seguimientos", value => {
      if (Array.isArray(value)) setSeguimientos(value);
    }, error => console.error("No se pudieron actualizar los seguimientos en tiempo real:", error));
    const unsubscribeCampaigns = subscribeSharedData("casasolar:campaigns", value => {
      if (Array.isArray(value)) setCampaigns(value);
    }, error => console.error("No se pudieron actualizar las campañas en tiempo real:", error));
    const unsubscribeDiscounts = subscribeSharedData("casasolar:descuentos", value => {
      if (Array.isArray(value)) setDescuentoSolicitudes(value);
    }, error => console.error("No se pudo actualizar la bandeja de descuentos:", error));
    return () => { unsubscribeProfile(); unsubscribeSellers(); unsubscribeContacts(); unsubscribeQuotes(); unsubscribeFollowups(); unsubscribeCampaigns(); unsubscribeDiscounts(); };
  }, [currentUser?.uid]);

  const persistVendedores = (list) => { setVendedores(list); storageSet("casasolar:vendedores", list, true); };
  const persistContactos = (list) => { setContactos(list); storageSet("casasolar:contactos", list, true); };
  const persistCotizaciones = (list) => { setCotizaciones(list); storageSet("casasolar:cotizaciones", list, true); };
  const persistSeguimientos = (list) => { setSeguimientos(list); storageSet("casasolar:seguimientos", list, true); };
  const persistCampaigns = (list) => { setCampaigns(list); storageSet("casasolar:campaigns", list, true); };

  const handleLogin = (email, password) => loginWithEmail(email, password);

  const handleLogout = async () => {
    await logoutFirebase();
    setTab("dashboard");
    setSelectedId(null);
  };

  const addContacto = (form) => persistContactos([{ ...form, id: uid() }, ...contactos]);
  const importContactos = (rows, mode) => {
    const phone = value => String(value || "").replace(/\D/g, "").replace(/^502/, "");
    const name = value => String(value || "").trim().toLowerCase();
    const next = [...contactos];
    let added = 0, updated = 0, skipped = 0;
    rows.forEach(row => {
      const index = next.findIndex(item => (phone(row.telefono) && phone(item.telefono) === phone(row.telefono)) || name(item.nombre) === name(row.nombre));
      if (index < 0) { next.unshift({ ...row, id: uid() }); added += 1; return; }
      const canUpdate = currentUser.rol === "Jefe" || next[index].vendedor === currentUser.nombre;
      if (!canUpdate) { skipped += 1; return; }
      if (mode === "update") {
        const available = Object.fromEntries(Object.entries(row).filter(([, value]) => value !== "" && value != null));
        next[index] = { ...next[index], ...available, id: next[index].id };
        updated += 1;
      } else skipped += 1;
    });
    persistContactos(next);
    window.alert(`Importación terminada: ${added} nuevos, ${updated} actualizados y ${skipped} omitidos.`);
  };
  const updateContacto = (updated) => {
    persistContactos(contactos.map(c => c.id === updated.id ? updated : c));
    const cliente = { id: updated.id, nombre: updated.nombre || "", telefono: updated.telefono || "", email: updated.email || "", dpi: updated.dpi || "", nit: updated.nit || "C/F", direccion: updated.direccion || "", municipio: updated.municipio || "", departamento: updated.departamento || "" };
    persistCotizaciones(cotizaciones.map(q => q.contactoId === updated.id ? { ...q, contactoNombre: updated.nombre, cliente } : q));
  };
  const assignContactos = async (ids, seller) => {
    const selectedIds = new Set(ids);
    persistContactos(contactos.map(item => selectedIds.has(item.id) ? { ...item, vendedor: seller } : item));
    persistCotizaciones(cotizaciones.map(item => selectedIds.has(item.contactoId) ? { ...item, vendedor: seller } : item));
    const followupIds = seguimientos.filter(item => selectedIds.has(item.contactoId)).map(item => item.id);
    setSeguimientos(current => current.map(item => selectedIds.has(item.contactoId) ? { ...item, vendedor: seller } : item));
    if (followupIds.length) await updateSharedDataRecords("casasolar:seguimientos", followupIds, { vendedor: seller });
    window.alert(`${ids.length} cliente${ids.length === 1 ? "" : "s"} asignado${ids.length === 1 ? "" : "s"} a ${seller}.`);
  };
  const addCotizacion = (data) => {
    const contacto = contactos.find(c => c.id === data.contactoId);
    const year = new Date().getFullYear();
    const max = cotizaciones
      .filter(c => String(c.numero || "").startsWith(`CS-${year}-`))
      .reduce((value, c) => Math.max(value, Number(String(c.numero).split("-").pop()) || 0), 0);
    const numero = `CS-${year}-${String(max + 1).padStart(4, "0")}`;
    const validDate = new Date(`${data.fecha}T12:00:00`);
    validDate.setDate(validDate.getDate() + 30);
    const cliente = contacto ? {
      id: contacto.id, nombre: contacto.nombre || "", telefono: contacto.telefono || "",
      email: contacto.email || "", dpi: contacto.dpi || "", nit: contacto.nit || "C/F",
      direccion: contacto.direccion || "", municipio: contacto.municipio || "", departamento: contacto.departamento || "",
    } : null;
    persistCotizaciones([{ ...data, id: uid(), numero, validaHasta: validDate.toISOString().slice(0, 10), contactoNombre: contacto?.nombre, cliente }, ...cotizaciones]);
  };
  const updateCotizacionEstado = (id, estado) => persistCotizaciones(cotizaciones.map(c => c.id === id ? { ...c, estado, fechaVenta: estado === "Aceptada" ? (c.fechaVenta || todayISO()) : c.fechaVenta } : c));
  const updateCotizacion = async (updated) => {
    const shared = await storageGet("casasolar:cotizaciones", true);
    const source = Array.isArray(shared) ? shared : cotizaciones;
    const previousQuote = source.find(item => item.id === updated.id);
    const next = source.map(c => {
      if (c.id !== updated.id) return c;
      const discount = updated.descuentoAutorizado;
      const syncedOrder = updated.ordenPedido && discount ? {
        ...updated.ordenPedido,
        descuentoAutorizadoMonto: discount.monto,
        descuentoAutorizadoTipo: discount.tipo,
        descuentoAutorizadoValor: discount.valor,
        descuentoAutorizadoPor: discount.autorizadoPor,
        descuentoAutorizadoFecha: discount.autorizadoEn,
        totalAntesDescuento: updated.totalOriginal,
        totalConDescuento: updated.total,
        saldo: updated.ordenPedido.estadoPago === "Cancelado" ? "0" : String(Math.max(0, Number(updated.total || 0) - Number(updated.ordenPedido.abono || 0))),
      } : updated.ordenPedido;
      return { ...updated, ordenPedido: syncedOrder, fechaVenta: updated.estado === "Aceptada" ? (updated.fechaVenta || c.fechaVenta || todayISO()) : updated.fechaVenta };
    });
    setCotizaciones(next);
    await storageSet("casasolar:cotizaciones", next, true);
    const previousInstallationDate = previousQuote?.ordenPedido?.fechaInstalacion || "";
    const installationDate = updated.ordenPedido?.fechaInstalacion || "";
    if (installationDate && installationDate !== previousInstallationDate && updated.contactoId) {
      const contact = contactos.find(item => item.id === updated.contactoId);
      const eventKey = `instalacion-programada:${updated.id}:${installationDate}`;
      const latestFollowups = await storageGet("casasolar:seguimientos", true);
      if (!Array.isArray(latestFollowups) || !latestFollowups.some(item => item.eventoClave === eventKey)) {
        const record = {
          id: uid(), contactoId: updated.contactoId, contactoNombre: contact?.nombre || updated.contactoNombre || "Cliente",
          tipo: previousInstallationDate ? "Instalación reprogramada" : "Instalación programada",
          notas: `${previousInstallationDate ? `Instalación cambiada de ${previousInstallationDate} a` : "Instalación programada para"} ${installationDate}${updated.ordenPedido?.horario ? ` · ${updated.ordenPedido.horario}` : ""}. Orden ${updated.ordenNumero || updated.numero}.`,
          proximoSeguimiento: installationDate, vendedor: updated.vendedor || contact?.vendedor || currentUser.nombre,
          fecha: todayISO(), fechaHora: new Date().toISOString(), creadoEn: new Date().toISOString(), creadoPorEmail: currentUser.email || "",
          origen: "Sistema", cotizacionId: updated.id, eventoClave: eventKey,
        };
        setSeguimientos(current => current.some(item => item.eventoClave === eventKey) ? current : [record, ...current]);
        await appendSharedData("casasolar:seguimientos", record);
      }
    }
    if (updated.descuentoSolicitud?.id) {
      const latestQueue = await storageGet("casasolar:descuentos", true);
      const sourceQueue = Array.isArray(latestQueue) ? latestQueue : descuentoSolicitudes;
      const queueRecord = { ...updated.descuentoSolicitud, cotizacionId: updated.id, numero: updated.numero, contactoId: updated.contactoId, contactoNombre: updated.contactoNombre, vendedor: updated.vendedor, totalBase: updated.totalOriginal ?? updated.total };
      const queueNext = sourceQueue.some(item => item.id === queueRecord.id)
        ? sourceQueue.map(item => item.id === queueRecord.id ? queueRecord : item)
        : [queueRecord, ...sourceQueue];
      setDescuentoSolicitudes(queueNext);
      await storageSet("casasolar:descuentos", queueNext, true);
    }
    return next.find(c => c.id === updated.id);
  };
  const addSeguimiento = async (data) => {
    const contacto = contactos.find(c => c.id === data.contactoId);
    const record = { ...data, id: uid(), contactoNombre: contacto?.nombre, creadoEn: new Date().toISOString(), creadoPorEmail: currentUser.email || "" };
    setSeguimientos(current => current.some(item => item.id === record.id) ? current : [record, ...current]);
    try {
      await appendSharedData("casasolar:seguimientos", record);
    } catch (error) {
      setSeguimientos(current => current.filter(item => item.id !== record.id));
      console.error("No se pudo guardar el seguimiento:", error);
      window.alert("No se pudo guardar el seguimiento en Firebase. Revisa la conexión e inténtalo nuevamente.");
      throw error;
    }
  };
  const addVendedor = (nombre, telefono) => persistVendedores([...vendedores, { id: uid(), nombre, telefono }]);
  const createUserAccess = async ({ nombre, email, password, rol, telefono, departamentosCobertura }) => {
    const profile = await createCRMUser({ nombre, email, password, rol, telefono, departamentosCobertura, createdBy: currentUser });
    const existing = vendedores.find(item => String(item.email || "").toLowerCase() === profile.email);
    if (existing) {
      persistVendedores(vendedores.map(item => item.id === existing.id ? { ...item, ...profile } : item));
    } else {
      persistVendedores([...vendedores, { id: uid(), ...profile }]);
    }
  };
  const updateVendedor = async (updated) => {
    const previous = vendedores.find(v => v.id === updated.id);
    const oldName = previous?.nombre || "";
    const newName = String(updated.nombre || "").trim();
    if (!newName) return window.alert("El nombre del vendedor no puede quedar vacío.");
    if (vendedores.some(v => v.id !== updated.id && v.nombre.toLowerCase() === newName.toLowerCase())) {
      return window.alert("Ya existe otro vendedor con ese nombre.");
    }
    const saved = { ...updated, nombre: newName };
    persistVendedores(vendedores.map(v => v.id === saved.id ? saved : v));
    if (oldName && oldName !== newName) {
      persistContactos(contactos.map(item => item.vendedor === oldName ? { ...item, vendedor: newName } : item));
      persistCotizaciones(cotizaciones.map(item => item.vendedor === oldName ? { ...item, vendedor: newName } : item));
      const followupIds = seguimientos.filter(item => item.vendedor === oldName).map(item => item.id);
      setSeguimientos(current => current.map(item => item.vendedor === oldName ? { ...item, vendedor: newName } : item));
      if (followupIds.length) await updateSharedDataRecords("casasolar:seguimientos", followupIds, { vendedor: newName });
      persistCampaigns(campaigns.map(campaign => ({
        ...campaign,
        sends: (campaign.sends || []).map(send => send.vendedor === oldName ? { ...send, vendedor: newName } : send),
      })));
      if (currentUser.uid === saved.uid || currentUser.email === saved.email || currentUser.nombre === oldName) {
        setCurrentUser(user => ({ ...user, nombre: newName }));
      }
    }
  };
  const resetUserPassword = async (user) => {
    if (!user.email) return window.alert("Este colaborador no tiene un correo de acceso registrado.");
    if (!window.confirm(`¿Enviar a ${user.email} un enlace seguro para cambiar su contraseña?`)) return;
    try {
      await sendCRMPasswordReset(user.email);
      window.alert(`Enlace de restablecimiento enviado a ${user.email}.`);
    } catch (error) {
      console.error("No se pudo enviar el restablecimiento:", error);
      window.alert("No se pudo enviar el enlace. Verifica el correo y la conexión.");
    }
  };
  const toggleUserAccess = async (user, activate) => {
    if (String(user.email || "").toLowerCase() === "leyla.flores@gmail.com") return window.alert("El acceso principal de Leyla no puede suspenderse desde esta pantalla.");
    if (!window.confirm(`${activate ? "¿Reactivar" : "¿Suspender"} el acceso de ${user.nombre}?`)) return;
    try {
      if (user.uid) await setCRMUserActive(user.uid, activate, currentUser.nombre);
      persistVendedores(vendedores.map(item => item.id === user.id ? { ...item, activo: activate, estadoAcceso: activate ? "Activo" : "Suspendido", estadoAccesoActualizadoEn: new Date().toISOString(), estadoAccesoActualizadoPor: currentUser.nombre } : item));
      window.alert(`${user.nombre} quedó ${activate ? "activo" : "suspendido"}.`);
    } catch (error) {
      console.error("No se pudo cambiar el acceso:", error);
      window.alert("No se pudo cambiar el acceso. El usuario debe tener un acceso de Firebase asociado.");
    }
  };
  const removeVendedor = async (user) => {
    if (String(user.email || "").toLowerCase() === "leyla.flores@gmail.com") return window.alert("El acceso principal de Leyla no puede eliminarse.");
    if (!window.confirm(`¿Eliminar a ${user.nombre} del equipo? Su historial de clientes, ventas y seguimientos se conservará para auditoría, pero su acceso quedará suspendido.`)) return;
    try {
      if (user.uid) await setCRMUserActive(user.uid, false, currentUser.nombre);
      persistVendedores(vendedores.filter(item => item.id !== user.id));
      window.alert(`${user.nombre} fue eliminado del equipo y su acceso quedó suspendido.`);
    } catch (error) {
      console.error("No se pudo eliminar al colaborador:", error);
      window.alert("No se pudo completar la eliminación. No se hizo ningún cambio para evitar dejar el acceso activo.");
    }
  };

  const selectedContact = selectedId ? contactos.find(c => c.id === selectedId) : null;

  const promoToken = window.location.pathname.match(/\/p\/([a-f0-9]{24})\/?$/i)?.[1] || new URLSearchParams(window.location.search).get("promo");
  if (promoToken) return <PublicPromotion token={promoToken} />;

  if (loading) return <div className="loading-wrap"><Sun size={22} className="spin" /></div>;

  return (
    <div className="app-root">
      <style>{CSS}</style>
      {!currentUser ? (
        <LoginScreen onLogin={handleLogin} />
      ) : (
        <div className="app-shell">
          <Sidebar tab={tab} setTab={(t) => { setTab(t); setSelectedId(null); }} currentUser={currentUser} cotizaciones={cotizaciones} descuentoSolicitudes={descuentoSolicitudes} onLogout={handleLogout} />
          <main className="main">
            {tab === "dashboard" && (
              <Dashboard contactos={contactos} cotizaciones={cotizaciones} seguimientos={seguimientos} currentUser={currentUser} vendedores={vendedores} />
            )}
            {tab === "calculadora" && <RouteCalculator cotizaciones={cotizaciones} currentUser={currentUser} onUpdateCotizacion={updateCotizacion} />}
            {tab === "contactos" && !selectedContact && (
              <ContactosView contactos={contactos} vendedores={vendedores} currentUser={currentUser}
                onAdd={addContacto} onImport={importContactos} onAssign={assignContactos} onOpen={setSelectedId} />
            )}
            {tab === "contactos" && selectedContact && (
              <ContactDetail contacto={selectedContact} cotizaciones={cotizaciones} seguimientos={seguimientos}
                vendedores={vendedores} currentUser={currentUser} onBack={() => setSelectedId(null)}
                onUpdateContacto={updateContacto} onAddCotizacion={addCotizacion} onUpdateCotizacion={updateCotizacion} onAddSeguimiento={addSeguimiento} />
            )}
            {tab === "cotizaciones" && (
              <CotizacionesView cotizaciones={cotizaciones} contactos={contactos} vendedores={vendedores}
                currentUser={currentUser} onAdd={addCotizacion} onUpdateEstado={updateCotizacionEstado} onUpdateCotizacion={updateCotizacion} />
            )}
            {tab === "reportes" && <SalesReportsView cotizaciones={cotizaciones} vendedores={vendedores} currentUser={currentUser} />}
            {tab === "seguimientos" && (
              <SeguimientosView seguimientos={seguimientos} contactos={contactos} currentUser={currentUser} onAdd={addSeguimiento} />
            )}
            {tab === "campanas" && <CampaignsView campaigns={campaigns} contactos={contactos} currentUser={{ ...currentUser, telefono: vendedores.find(v => v.nombre === currentUser.nombre)?.telefono || "" }} onChange={persistCampaigns} />}
            {tab === "catalogo" && <CatalogoView />}
            {tab === "ordenes-tecnicas" && <TechnicalOrdersView cotizaciones={cotizaciones} contactos={contactos} vendedores={vendedores} currentUser={currentUser} onUpdate={updateCotizacion} />}
            {tab === "informes-tecnicos" && <InstallationReportsView cotizaciones={cotizaciones} contactos={contactos} currentUser={currentUser} />}
            {tab === "descuentos" && <DiscountRequestsView cotizaciones={cotizaciones} contactos={contactos} solicitudes={descuentoSolicitudes} currentUser={currentUser} onUpdate={updateCotizacion} />}
            {tab === "programacion" && <OperationsView mode="programacion" cotizaciones={cotizaciones} contactos={contactos} currentUser={currentUser} onUpdate={updateCotizacion} />}
            {tab === "bodega" && <OperationsView mode="bodega" cotizaciones={cotizaciones} contactos={contactos} currentUser={currentUser} onUpdate={updateCotizacion} />}
            {tab === "facturacion" && <OperationsView mode="facturacion" cotizaciones={cotizaciones} contactos={contactos} currentUser={currentUser} onUpdate={updateCotizacion} />}
            {tab === "planificacion" && <PlanningView cotizaciones={cotizaciones} contactos={contactos} />}
            {tab === "equipo" && currentUser.rol === "Jefe" && (
              <EquipoView vendedores={vendedores} currentUser={currentUser} onAdd={addVendedor} onCreateAccess={createUserAccess} onUpdate={updateVendedor} onRemove={removeVendedor} onResetPassword={resetUserPassword} onToggleAccess={toggleUserAccess} />
            )}
          </main>
        </div>
      )}
    </div>
  );
}

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600&family=Inter:wght@400;500;600&family=IBM+Plex+Mono:wght@500&display=swap');

.app-root { font-family: 'Inter', sans-serif; color: #1B2430; background: #F7F5F0; min-height: 600px; border-radius: 12px; overflow: hidden; }
.app-root * { box-sizing: border-box; }
h1,h2,h3 { font-family: 'Space Grotesk', sans-serif; margin: 0; font-weight: 600; }
p { margin: 4px 0 0; color: #667085; font-size: 13.5px; }
.muted { color: #8A8F98; font-size: 12.5px; }

.loading-wrap { display:flex; align-items:center; justify-content:center; min-height: 400px; color:#E30613; }
.bulk-bar { display:flex; align-items:center; gap:12px; flex-wrap:wrap; background:#fff; border:1px solid #E5E1D8; border-radius:10px; padding:10px 12px; margin-bottom:12px; }
.bulk-bar label { display:flex; align-items:center; gap:7px; }
.spin { animation: spin 1.2s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

/* Login */
.login-wrap { display:flex; flex-direction:column; align-items:center; justify-content:center; padding: 48px 24px; background: linear-gradient(180deg,#111316 0%, #1B1E22 55%, #F7F5F0 55%); min-height: 560px; }
.login-hero { text-align:center; color:#fff; margin-bottom: 28px; }
.login-logo { height:46px; width:auto; margin: 0 auto 18px; display:block; }
.login-hero h1 { font-size: 26px; color:#fff; }
.login-hero p { color: #C9CBCE; }
.login-card { background:#fff; border-radius:16px; padding:28px; width: 100%; max-width: 360px; box-shadow: 0 8px 30px rgba(11,37,69,0.15); display:flex; flex-direction:column; gap: 4px; }
.role-toggle { display:flex; gap:8px; margin: 6px 0 18px; }
.role-toggle button { flex:1; padding:9px; border-radius:8px; border:1px solid #E4E0D8; background:#fff; font-size:13px; cursor:pointer; font-weight:500; }
.role-toggle button.active { background:#14171A; color:#fff; border-color:#14171A; }
.login-note { font-size: 11.5px; color:#8A8F98; text-align:center; margin-top:10px; }
.login-error { font-size: 12px; color:#9B1017; margin: -6px 0 12px; }

/* Shell */
.app-shell { display:flex; min-height: 600px; }
.sidebar { width: 210px; background:#14171A; color:#E4E8F0; display:flex; flex-direction:column; padding: 18px 12px; flex-shrink:0; }
.brand { display:flex; align-items:center; gap:9px; padding: 4px 8px 22px; font-family:'Space Grotesk',sans-serif; font-weight:600; font-size:15px; color:#fff; }
.brand-icon { width:26px; height:26px; flex-shrink:0; }
.nav-item { display:flex; align-items:center; gap:10px; width:100%; text-align:left; background:none; border:none; color:#9AA0A6; padding:9px 10px; border-radius:8px; font-size:13.5px; cursor:pointer; margin-bottom:2px; }
.nav-item:hover { background: rgba(255,255,255,0.06); color:#fff; }
.nav-item.active { background:#E30613; color:#fff; font-weight:600; }
.sidebar-footer { margin-top:auto; padding-top: 14px; border-top: 1px solid rgba(255,255,255,0.1); }
.user-chip { display:flex; align-items:center; gap:8px; margin-bottom:10px; }
.avatar { width:30px; height:30px; border-radius:50%; background:#E30613; color:#fff; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:600; flex-shrink:0; }
.user-name { font-size:12.5px; font-weight:500; color:#fff; }
.user-role { font-size:11px; color:#9AA0A6; }

.main { flex:1; padding: 26px 30px; overflow-y:auto; max-height: 640px; }
.page-head { margin-bottom: 20px; }
.page-head.row, .row { display:flex; align-items:center; justify-content:space-between; }

/* KPIs */
.kpi-grid { display:grid; grid-template-columns: repeat(4,1fr); gap:12px; margin-bottom: 22px; }
.kpi-card { background:#fff; border:1px solid #E4E0D8; border-radius:12px; padding:14px 16px; }
.kpi-label { font-size:12px; color:#8A8F98; margin-bottom:6px; }
.kpi-value { font-family:'IBM Plex Mono',monospace; font-size:22px; font-weight:500; color:#14171A; }

.section-card { background:#fff; border:1px solid #E4E0D8; border-radius:12px; padding:18px 20px; margin-bottom:16px; }
.section-card h3 { font-size:14px; margin-bottom:12px; }

/* Pipeline signature element */
.pipeline { display:flex; gap:10px; overflow-x:auto; padding-top:4px; }
.pipeline-col { display:flex; flex-direction:column; align-items:center; min-width:66px; }
.pipeline-count { font-family:'IBM Plex Mono',monospace; font-size:15px; font-weight:500; margin-bottom:6px; }
.pipeline-panel { display:flex; flex-direction:column-reverse; gap:2px; background:#14171A; padding:4px; border-radius:4px; }
.cell { width:44px; height:6px; background:#1D3A63; border-radius:1px; }
.cell.lit { background:#E30613; }
.pipeline-label { font-size:10.5px; color:#8A8F98; margin-top:8px; text-align:center; }

.mini-list { display:flex; flex-direction:column; gap:0; }
.mini-row { display:flex; align-items:center; gap:14px; padding:8px 0; border-bottom:1px solid #F0EEE7; font-size:13px; }
.mini-row:last-child { border-bottom:none; }

/* Tables */
.table { width:100%; border-collapse:collapse; font-size:13px; }
.table th { text-align:left; font-size:11.5px; text-transform:uppercase; letter-spacing:0.03em; color:#8A8F98; padding:8px 6px; border-bottom:1px solid #E4E0D8; }
.table td { padding:9px 6px; border-bottom:1px solid #F0EEE7; }
.table.small td, .table.small th { padding:6px 4px; font-size:12.5px; }

/* Filters / search */
.filters { display:flex; gap:10px; margin-bottom:16px; flex-wrap:wrap; }
.search-box { display:flex; align-items:center; gap:8px; background:#fff; border:1px solid #E4E0D8; border-radius:8px; padding:0 10px; flex:1; min-width:200px; }
.search-box input { border:none; outline:none; padding:9px 0; font-size:13px; width:100%; background:transparent; }
.filter-select { width:auto; min-width:160px; }

/* Inputs */
.input { width:100%; border:1px solid #E4E0D8; border-radius:8px; padding:9px 10px; font-size:13.5px; font-family:inherit; margin-bottom:12px; background:#fff; color:#1B2430; }
.input.compact { margin-bottom:0; padding:5px 8px; font-size:12.5px; }
.field-label { font-size:12px; font-weight:500; color:#4A5568; margin-bottom:4px; display:block; }
.row-2 { display:grid; grid-template-columns: 1fr 1fr; gap:12px; }

/* Buttons */
.btn-primary { background:#E30613; color:#fff; border:none; padding:10px 16px; border-radius:8px; font-weight:600; font-size:13.5px; cursor:pointer; display:inline-flex; align-items:center; gap:6px; }
.btn-primary:disabled { opacity:0.5; cursor:not-allowed; }
.btn-ghost { background:none; border:1px solid #E4E0D8; padding:9px 14px; border-radius:8px; font-size:13px; cursor:pointer; display:inline-flex; align-items:center; gap:6px; color:#1B2430; }
.btn-ghost.small { padding:6px 10px; font-size:12px; margin-bottom:12px; }
.icon-btn { background:none; border:none; cursor:pointer; color:#8A8F98; padding:4px; display:flex; }
.icon-btn:hover { color:#C1502E; }

/* Cards / lists */
.card-list { display:flex; flex-direction:column; gap:8px; }
.contact-row, .seg-row { display:flex; align-items:center; gap:14px; background:#fff; border:1px solid #E4E0D8; border-radius:10px; padding:12px 14px; cursor:pointer; }
.contact-row:hover { border-color:#E30613; }
.channel-icon { width:34px; height:34px; border-radius:8px; background:#FBE1E1; color:#9B1017; display:flex; align-items:center; justify-content:center; flex-shrink:0; }
.channel-icon.lg { width:44px; height:44px; }
.contact-main { flex:1; min-width:0; }
.contact-name { font-weight:500; font-size:14px; }
.contact-sub { font-size:12px; color:#8A8F98; }
.contact-date { font-size:12px; white-space:nowrap; }
.follow-client-row { cursor:default; }
.follow-preview { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:620px; margin-top:2px; }
.follow-next { color:#9B1017; margin-top:3px; }
.follow-open { margin:0; flex-shrink:0; }
.follow-thread-modal { max-width:680px; }
.follow-thread { padding-top:22px; }
.follow-message { display:grid; grid-template-columns:32px 1fr; gap:10px; position:relative; padding-bottom:16px; }
.follow-dot { width:30px; height:30px; border-radius:50%; background:#FBE1E1; color:#9B1017; display:flex; align-items:center; justify-content:center; z-index:1; }
.follow-line { position:absolute; left:14px; top:29px; bottom:-1px; width:2px; background:#F1C5C5; }
.follow-bubble { background:#F7F5F0; border:1px solid #E4E0D8; border-radius:10px; padding:11px 13px; }
.follow-meta { display:flex; justify-content:space-between; gap:10px; font-size:12px; }
.follow-meta span { color:#8A8F98; }
.follow-bubble p { margin:7px 0; font-size:13px; white-space:pre-wrap; }
.follow-bubble small { display:flex; align-items:center; gap:5px; color:#9B1017; }

.empty-state { text-align:center; padding:40px 20px; color:#8A8F98; font-size:13.5px; background:#fff; border:1px dashed #E4E0D8; border-radius:12px; }

/* Badges */
.badge { font-size:11px; font-weight:600; padding:4px 9px; border-radius:20px; white-space:nowrap; }
.badge-sky { background:#E6F1FB; color:#0C447C; }
.badge-brand { background:#FBE1E1; color:#9B1017; }
.badge-brandDeep { background:#F5B3B3; color:#7A0A10; }
.badge-success { background:#EAF3DE; color:#27500A; }
.badge-danger { background:#FCEBEB; color:#791F1F; }
.badge-gray { background:#F1EFE8; color:#444441; }
.badge-green { background:#DCFCE7; color:#166534; }

/* Detail */
.detail-head { display:flex; align-items:center; gap:14px; margin-bottom:14px; }
.detail-meta { display:flex; gap:20px; flex-wrap:wrap; font-size:12.5px; color:#4A5568; margin-bottom:16px; }

/* Modal */
.modal-overlay { position:fixed; inset:0; background:rgba(11,37,69,0.4); display:flex; align-items:center; justify-content:center; z-index:50; padding:20px; }
.modal { background:#fff; border-radius:14px; width:100%; max-width:480px; max-height:88vh; display:flex; flex-direction:column; }
.modal.quote-modal { max-width:1080px; }
.modal.modal-wide { max-width:900px; }
.modal-head { display:flex; align-items:center; justify-content:space-between; padding:16px 20px; border-bottom:1px solid #F0EEE7; }
.modal-body { padding:18px 20px; overflow-y:auto; }
.modal-foot { display:flex; justify-content:flex-end; gap:10px; padding:14px 20px; border-top:1px solid #F0EEE7; }
.modal-body h4 { margin:8px 0 12px; padding-bottom:7px; color:#E30613; border-bottom:1px solid #F0EEE7; }
.form-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:0 12px; }
.client-preview { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:7px 18px; background:#F7F5F0; border:1px solid #E8E4DA; border-radius:9px; padding:11px 13px; margin:-5px 0 16px; font-size:12px; color:#4A5568; }
.client-preview .full { grid-column:1/-1; }
.item-row { display:flex; gap:8px; align-items:center; margin-bottom:12px; }
.item-row .input { margin-bottom:0; }
.item-row .qty { width:70px; }
.item-row .price { width:100px; }
.total-line { text-align:right; font-size:15px; padding:8px 0; font-family:'IBM Plex Mono',monospace; }
.quote-item-grid { display:grid; grid-template-columns: 1.2fr 1.2fr 1fr 70px 110px 110px auto; align-items:start; }
.quote-item-grid .input, .quote-item-grid .btn-ghost { width:100%; margin-bottom:8px; }
.quote-category-row { display:flex; align-items:center; gap:12px; margin:-3px 0 12px; }
.quote-category-row label { width:240px; flex-shrink:0; }
.quote-category-row .input { margin-bottom:0; }
.quote-category-row p { font-size:11px; }
.quote-actions { display:flex; align-items:center; gap:5px; flex-wrap:wrap; min-width:270px; }
.quote-actions .btn-ghost.small { margin-bottom:0; padding:5px 7px; }
.send-count { font-size:10.5px; color:#667085; border-bottom:1px dotted #667085; cursor:help; }
.change-user-btn { color:#fff !important; border-color:rgba(255,255,255,0.32) !important; }
.change-user-btn:hover { color:#fff !important; background:rgba(255,255,255,0.08); }
.nav-item.nav-alert { color:#fff; background:#7A1D24; box-shadow:inset 3px 0 #FFCB45; }
.discount-btn { border-color:#E30613; color:#9B1017; }
.discount-status { font-size:10px; font-weight:600; padding:4px 7px; border-radius:12px; }
.discount-status.pendiente { background:#FFF2CC; color:#7A4D00; }
.discount-status.autorizado { background:#EAF3DE; color:#27500A; }
.discount-status.rechazado { background:#FCEBEB; color:#791F1F; }
.discount-status.no.autorizado { background:#FCEBEB; color:#791F1F; }
.discount-decision-buttons { display:flex; flex-direction:column; align-items:stretch; gap:5px; min-width:165px; }
.discount-decision-buttons .small { justify-content:center; margin:0; white-space:nowrap; padding:6px 8px; }
.discount-decision-buttons .reject-discount { color:#791F1F; border-color:#E7B6B6; }
.discount-requests-table td { vertical-align:top; }
.discount-modal { max-width:540px; }
.pending-discount { display:flex; align-items:center; gap:8px; background:#FFF7DD; color:#6E4E00; border-radius:8px; padding:10px 12px; margin-bottom:14px; font-size:12px; }
.discount-summary { display:grid; grid-template-columns:1fr 1fr; gap:10px; margin:8px 0 14px; }
.discount-summary > div { background:#F7F5F0; border-radius:9px; padding:11px; display:flex; flex-direction:column; gap:5px; }
.discount-summary span { font-size:11px; color:#667085; }
.discount-summary strong { font-family:'IBM Plex Mono',monospace; }
.audit-note { display:flex; align-items:center; gap:8px; font-size:11px; color:#4A5568; background:#EAF3DE; border-radius:8px; padding:10px 12px; }

/* Administración de usuarios */
.user-access-card { margin-bottom:16px; border-top:3px solid #E30613; }
.section-title { display:flex; gap:10px; align-items:flex-start; margin-bottom:15px; }
.section-title svg { color:#E30613; flex-shrink:0; }
.section-title h3 { font-size:16px; }
.user-access-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:0 12px; }
.user-access-grid label:last-child { grid-column:1/-1; }
.form-success { color:#27500A; background:#EAF3DE; padding:9px 11px; border-radius:8px; margin:0 0 12px; }
.draft-note { display:block; color:#64820F; font-size:10.5px; margin-top:3px; }
.order-evaluation-summary { background:#F7F5F0; border:1px solid #E4E0D8; border-left:4px solid #E30613; border-radius:10px; padding:14px; margin-bottom:18px; }
.modal-body .order-summary-head h4 { color:#1B2430; border:0; padding:0; margin:0; }
.order-summary-head { display:flex; align-items:flex-start; gap:9px; margin-bottom:12px; }
.order-summary-head svg { color:#E30613; flex-shrink:0; }
.order-summary-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; }
.order-summary-grid > div, .quoted-equipment > div { background:#fff; border-radius:7px; padding:8px 10px; display:flex; flex-direction:column; gap:3px; }
.order-summary-grid span, .quoted-equipment > span { color:#667085; font-size:10.5px; text-transform:uppercase; letter-spacing:.04em; }
.order-summary-grid strong, .quoted-equipment strong { font-size:12px; }
.quoted-equipment { margin-top:10px; display:flex; flex-direction:column; gap:6px; }
.quoted-equipment small { color:#667085; font-size:10.5px; }
.technical-order-row { width:100%; border:1px solid #E4E0D8; background:#fff; border-radius:9px; padding:12px 14px; display:flex; justify-content:space-between; align-items:center; gap:12px; text-align:left; cursor:pointer; }
.technical-order-row:hover { border-color:#E30613; background:#FFF9F9; }
.technical-order-row > div { display:flex; flex-direction:column; gap:4px; }
.technical-order-row > div:last-child { align-items:flex-end; }
.technical-order-row span, .technical-order-row small { color:#667085; font-size:11.5px; }
.photo-links { display:flex; flex-wrap:wrap; gap:7px; margin:-3px 0 14px; }
.photo-links a { display:inline-flex; align-items:center; gap:5px; color:#9B1017; background:#FFF0F1; border:1px solid #F7C7CA; border-radius:7px; padding:7px 9px; font-size:11px; text-decoration:none; }
.paid-order-banner { display:flex; align-items:center; gap:8px; color:#166534; background:#DCFCE7; border:1px solid #86EFAC; border-radius:8px; padding:10px 12px; margin-bottom:12px; font-weight:700; }
.evaluation-type-buttons { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; margin-bottom:10px; }
.evaluation-type-buttons button { border:1px solid #D9D5CC; background:#fff; color:#344054; border-radius:9px; padding:10px; font:600 12px inherit; cursor:pointer; display:flex; align-items:center; justify-content:center; gap:6px; }
.evaluation-type-buttons button.active { border-color:#E30613; background:#FBE1E1; color:#9B1017; }
.evaluation-route-note { display:flex; align-items:center; gap:8px; background:#EEF4FF; color:#344054; border-radius:8px; padding:9px 11px; margin-bottom:15px; font-size:12px; }
.order-status-box { background:#F7F5F0; border:1px solid #E4E0D8; border-radius:8px; padding:9px 10px; min-height:38px; font-size:13px; }
.order-status-box.done { background:#DCFCE7; border-color:#86EFAC; color:#166534; font-weight:700; }
.authorized-discount-order { display:flex; align-items:center; gap:10px; background:#EAF3DE; border:1px solid #B6D79B; color:#27500A; border-radius:9px; padding:11px 13px; margin:4px 0 16px; }
.authorized-discount-order div { display:flex; flex-direction:column; gap:3px; }
.authorized-discount-order span { font-size:12px; }
.warranty-card { border:1px solid #E4E0D8; background:#FAF9F6; border-radius:10px; padding:14px; margin-bottom:15px; }
.warranty-approvals { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; margin-top:12px; }
.warranty-approvals > div { background:#fff; border:1px solid #E4E0D8; border-radius:9px; padding:11px; display:flex; flex-direction:column; gap:7px; }
.warranty-approvals > div > div { display:flex; gap:6px; margin-top:3px; }
.warranty-state { background:#FFF2CC; color:#7A4D00; border-radius:14px; padding:4px 8px; font-size:11px; align-self:flex-start; }
.warranty-state.approved { background:#EAF3DE; color:#27500A; }
.warranty-state.denied { background:#FCEBEB; color:#791F1F; }
.warranty-result { display:flex; align-items:center; justify-content:center; gap:7px; padding:11px; border-radius:9px; margin-top:12px; font-weight:700; }
.warranty-result.ready { background:#DCFCE7; color:#166534; border:1px solid #86EFAC; }
.warranty-result.blocked { background:#FFF2CC; color:#7A4D00; border:1px solid #F0D98B; }
.advances-section { margin-top:22px; border-top:4px solid #E30613; }
.advances-section .section-title p { font-size:12px; color:#667085; }
.planning-filters { display:flex; align-items:center; gap:16px; }
.planning-filters .role-toggle { margin:0; min-width:260px; }
.installation-report-card { margin-top:18px; padding:16px; border:1px solid #B7E2C6; border-radius:12px; background:#F4FBF6; }
.installation-report-card .btn-primary { margin-top:12px; }
.password-field { position:relative; display:block; }
.password-field .input { padding-right:42px; }
.password-field .icon-btn { position:absolute; right:5px; top:5px; }
.table-note { display:block; margin-top:4px; color:#8A8F98; font-size:11px; }
.planning-filters .input { margin:0; max-width:220px; }
.timeline-list { display:flex; flex-direction:column; gap:10px; }
.timeline-item { display:grid; grid-template-columns:100px 1fr; gap:14px; align-items:center; border-left:4px solid #E30613; background:#F7F5F0; border-radius:8px; padding:12px 14px; }
.timeline-item > strong { color:#9B1017; font-family:'IBM Plex Mono',monospace; }
.timeline-item h3 { font-size:14px; }
.report-head { display:flex; align-items:center; justify-content:space-between; gap:12px; }
.report-filters { display:flex; align-items:end; gap:10px; flex-wrap:wrap; }
.report-filters label { min-width:155px; flex:1; }
.report-filters .input { margin-bottom:0; }
.report-name { font-size:16px; line-height:1.2; }
.sales-chart { display:flex; flex-direction:column; gap:10px; margin-top:16px; }
.sales-bar-row { display:grid; grid-template-columns:65px minmax(120px,1fr) 105px; gap:10px; align-items:center; font-size:11.5px; }
.sales-bar-row > span { color:#667085; }
.sales-bar-row > strong { text-align:right; font-family:'IBM Plex Mono',monospace; font-size:11px; }
.sales-bar-track { height:16px; background:#F0EEE7; border-radius:10px; overflow:hidden; }
.sales-bar { height:100%; background:linear-gradient(90deg,#E30613,#FF5A5F); border-radius:10px; }

/* Calculadora de rutas */
.route-layout { display:grid; grid-template-columns:minmax(0,1.15fr) minmax(280px,.85fr); gap:16px; }
.route-form .btn-primary { width:100%; justify-content:center; }
.route-address-title { font-size:15px; margin:4px 0 12px; }
.route-address-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:0 10px; }
.address-preview { display:flex; align-items:flex-start; gap:8px; background:#F7F5F0; border-radius:8px; padding:10px; color:#4A5568; font-size:12px; margin:-4px 0 14px; }
.address-preview svg { color:#E30613; flex-shrink:0; }
.roundtrip-check { display:flex; align-items:center; gap:8px; font-size:12.5px; margin:0 0 14px; }
.route-error { background:#FCEBEB; color:#791F1F; border-radius:8px; padding:10px; font-size:12px; margin-bottom:12px; }
.route-result { display:flex; flex-direction:column; justify-content:center; }
.route-empty { min-height:260px; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; gap:9px; color:#8A8F98; }
.route-empty svg { color:#E30613; }
.route-empty strong { color:#1B2430; }
.route-empty span { max-width:260px; font-size:12px; }
.route-result-head { display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid #E4E0D8; padding-bottom:12px; margin-bottom:5px; }
.route-result-head span { color:#E30613; letter-spacing:.08em; font-size:10px; font-weight:600; }
.route-metric { display:flex; justify-content:space-between; padding:11px 0; border-bottom:1px solid #F0EEE7; font-size:13px; }
.route-formula { margin:13px 0 8px; color:#667085; font:12px 'IBM Plex Mono',monospace; text-align:right; }
.route-total { display:flex; justify-content:space-between; align-items:center; background:#14171A; color:#fff; border-radius:10px; padding:14px; }
.route-total strong { color:#fff; font:18px 'IBM Plex Mono',monospace; }
.route-result small { color:#8A8F98; line-height:1.4; margin-top:12px; }
.route-result .route-match-warning { color:#7A4D00; background:#FFF7DD; padding:8px 9px; border-radius:7px; }
.route-save-next { width:100%; justify-content:center; margin-top:12px; }
.route-attach { border-top:1px solid #E4E0D8; margin-top:14px; padding-top:14px; }
.route-attach .btn-primary { width:100%; justify-content:center; margin-bottom:10px; }
.route-attach .form-success { margin-top:2px; }
.route-note { font-size:11px; margin-top:0; }
.pending-transport-card { display:flex; justify-content:space-between; align-items:center; gap:12px; background:#FFF7DD; border:1px solid #F0D98B; border-radius:9px; padding:11px 12px; margin:0 0 15px; }
.pending-transport-card > div { display:flex; align-items:flex-start; gap:8px; }
.pending-transport-card svg { color:#9B1017; flex-shrink:0; }
.pending-transport-card span { display:flex; flex-direction:column; gap:3px; }
.pending-transport-card small { color:#6E4E00; font-size:10.5px; }
.pending-transport-card .btn-primary { flex-shrink:0; }

.catalog-grid { display:grid; grid-template-columns: repeat(auto-fill, minmax(200px,1fr)); gap:10px; }
.catalog-item { display:flex; align-items:center; gap:8px; background:#F7F5F0; border-radius:8px; padding:10px 12px; font-size:13px; }

@media (max-width: 720px) {
  .app-shell { flex-direction:column; }
  .sidebar { width:100%; flex-direction:row; align-items:center; overflow-x:auto; padding:10px; }
  .sidebar nav { display:flex; gap:4px; }
  .sidebar-footer { display:none; }
  .kpi-grid { grid-template-columns: repeat(2,1fr); }
  .row-2 { grid-template-columns: 1fr; }
  .quote-item-grid { grid-template-columns:1fr 1fr; }
  .quote-category-row { align-items:stretch; flex-direction:column; }
  .quote-category-row label { width:100%; }
  .form-grid { grid-template-columns:1fr; }
  .client-preview { grid-template-columns:1fr; }
  .client-preview .full { grid-column:auto; }
  .route-layout { grid-template-columns:1fr; }
  .route-address-grid { grid-template-columns:1fr; }
  .pending-transport-card { align-items:stretch; flex-direction:column; }
  .planning-filters { align-items:stretch; flex-direction:column; }
  .planning-filters .role-toggle, .planning-filters .input { min-width:0; max-width:none; width:100%; }
  .discount-summary { grid-template-columns:1fr; }
  .user-access-grid { grid-template-columns:1fr; }
  .user-access-grid label:last-child { grid-column:auto; }
  .order-summary-grid { grid-template-columns:1fr; }
  .evaluation-type-buttons { grid-template-columns:1fr; }
  .warranty-approvals { grid-template-columns:1fr; }
  .report-head { align-items:flex-start; flex-direction:column; }
  .sales-bar-row { grid-template-columns:52px minmax(80px,1fr) 90px; }
}

@media print {
  .sidebar, .report-head .btn-primary, .report-filters { display:none !important; }
  .app-root, .app-shell, .main { background:#fff !important; overflow:visible !important; min-height:0 !important; }
  .main { padding:0 !important; }
  .section-card, .kpi-card { box-shadow:none !important; break-inside:avoid; }
  .printable-report { color:#000; }
}
`;
